(41, 'Tour Tiết Kiệm Phố Cổ Hội An & Rừng Dừa Bảy Mẫu - Gói Tiết Kiệm', 'tour-tiet-kiem-pho-co-hoi-an-rung-dua-bay-mau-goi-41', 2, 'Gói Tiết Kiệm tối ưu hóa chi phí cho du khách tự túc bằng cách lược bỏ các dịch vụ ăn uống và đưa đón tùy chọn. Gói Tiêu Chuẩn mang đến hành trình tham quan đầy đủ với mức giá hợp lý nhất. Trải nghiệm chuyên sâu hơn của Trải nghiệm chèo thúng tại rừng dừa Bảy Mẫu và khám phá vẻ đẹp hoài cổ của phố cổ Hội An về đêm.', 'Kết hợp trải nghiệm sông nước và văn hóa phố cổ.', '[{"time": "07:30", "title": "Đón khách", "description": "Xe và hướng dẫn viên đón khách tại điểm hẹn trung tâm Đà Nẵng."}, {"time": "09:00", "title": "Tham quan Hội An", "description": "Khám phá các điểm nổi bật của Hội An, chụp ảnh và nghe giới thiệu về văn hóa địa phương."}, {"time": "12:00", "title": "Dùng bữa và nghỉ ngơi", "description": "Thưởng thức bữa ăn theo chương trình hoặc tự do trải nghiệm ẩm thực địa phương tùy gói tour."}, {"time": "15:30", "title": "Trải nghiệm bổ sung", "description": "Tiếp tục tham quan, mua sắm đặc sản hoặc tự do khám phá theo hướng dẫn của điều phối tour."}, {"time": "17:30", "title": "Kết thúc tour", "description": "Đưa khách về lại điểm hẹn ban đầu tại Đà Nẵng."}]'::jsonb, '["Xe đưa đón theo chương trình", "Hướng dẫn viên địa phương", "Vé tham quan theo lịch trình nếu có trong gói", "Nước uống trên xe", "Bảo hiểm du lịch cơ bản", "Nước uống đóng chai miễn phí trên xe (1 chai/người)"]'::jsonb, '["Chi phí cá nhân ngoài chương trình", "Bữa ăn và đồ uống không nêu trong phần bao gồm", "Phụ thu cuối tuần, lễ Tết nếu có", "Tiền tip cho hướng dẫn viên và tài xế", "Bữa ăn trưa và ăn tối tự túc trong suốt hành trình"]'::jsonb, '640000.00', '470000.00', '150000.00', 0, '7 giờ', '07:30', 'Trung tâm Đà Nẵng hoặc khách sạn trong khu vực nội thành', 30, 2, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780567178/danangtrip/tours/tour-real-variant-41/tour-41__tour-real-variant-41__p01.jpg', '["https://res.cloudinary.com/dmukxquza/