(101, 'Daily Golden Bridge and Ba Na Hills Tour from Da Nang', 'dacotours-daily-golden-bridge-ba-na-hills-from-da-nang-tours-by-local', 1, 'Embark on a thrilling adventure to the iconic Golden Bridge and Ba Na Hills, departing from Da Nang. This guided tour offers a unique blend of natural beauty, cultural experiences, and thrilling activities. Discover the majestic scenery, indulge in local cuisine, and create unforgettable memories. With a carefully crafted itinerary, this tour promises an exciting and enriching experience for all travelers.', 'Explore Golden Bridge and Ba Na Hills', '[{"time": "07:30", "title": "Pickup and Departure", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting journey to the Golden Bridge and Ba Na Hills."}, {"time": "09:00", "title": "Exploring Main Attractions", "description": "Start your adventure with a visit to the iconic Golden Bridge, suspended high above the hills, offering breathtaking views of the surrounding landscape. Explore the stunning architecture and take in the panoramic vistas."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Enjoy a delicious meal as part of your tour package or take the opportunity to explore local eateries and savor the authentic flavors of the region."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your journey with a visit to Ba Na Hills, where you can explore the scenic trails, take in the stunning views, and learn about the local culture and history. Don''t forget to capture the moment with plenty of photo opportunities."}, {"time": "17:30", "title": "Tour Conclusion", "description": "After an eventful day, our guide will escort you back to the initial meeting point, marking the end of your memorable tour to the Golden Bridge and Ba Na Hills."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour with English-speaking guide", "Entrance fees to Golden Bridge and Ba Na Hills", "Lunch as part of the tour package"]'::jsonb, '["Personal expenses and souvenirs", "Tips and gratuities for the guide and driver", "Optional activities not mentioned in the itinerary"]'::jsonb, '1650000.00', '1150000.00', '0.00', 0, '8 giờ', '08:00', 'Hotel lobby or designated pickup point', 30, 1, NULL, NULL, 'https://dacotours.com/wp-content/uploads/2025/08/Discovery.png', '["https://dacotours.com/wp-content/uploads/2025/08/Discovery.png", "https://dacotours.com/wp-content/uploads/2025/08/settings.png", "https://dacotours.com/wp-content/uploads/2025/08/booking.png", "https://dacotours.com/wp-content/uploads/2024/07/button.png", "https://dacotours.com/wp-content/uploads/2025/09/Golden-Bridge-768x432.jpg", "https://dacotours.com/wp-content/uploads/2025/08/gen-h-cau-vang-ba-na-hills-ne-768x520.jpg", "https://dacotours.com/wp-content/uploads/2024/09/gen-h-dacotours-ba-na-hills-768x659.jpg", "https://dacotours.com/wp-content/uploads/2025/09/ba-na-hils-ban-tay-vang.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(102, 'Ba Na Hills Tour From Da Nang', 'dananglocaltours-ba-na-hills-tour-from-da-nang-good-price-1-da-nang-local-tours', 1, 'Join our Ba Na Hills Tour From Da Nang to experience the breathtaking scenery and rich culture of central Vietnam. This guided tour takes you through the stunning hills, golden bridges, and picturesque villages, offering a unique blend of natural beauty, adventure, and local insights. With a carefully crafted itinerary, you''ll have the opportunity to immerse yourself in the local way of life, try delicious cuisine, and create unforgettable memories.', 'Explore Ba Na Hills', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Ba Na Hills adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your journey with a visit to the iconic Golden Bridge, followed by exploration of the Ba Na Hills'' scenic trails, gardens, and stunning viewpoints, offering panoramic views of the surrounding landscape."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy a delicious lunch at a local restaurant, included in your tour package, or opt for a self-guided culinary experience, trying some of the region''s specialties and taking a break to recharge for the rest of the day."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour with a visit to the Fantasy Park, an amusement park with various games and attractions, or explore the Debay Wine Cellar, learning about the local wine production and sampling some of the finest wines."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your Ba Na Hills Tour From Da Nang, filled with unforgettable experiences and memories of central Vietnam''s natural beauty and rich culture."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour with English-speaking guide", "Entrance fees to Ba Na Hills and Golden Bridge", "Lunch at a local restaurant", "Visit to Fantasy Park and Debay Wine Cellar"]'::jsonb, '["Personal expenses and gratuities", "Travel insurance", "Optional activities not mentioned in the itinerary"]'::jsonb, '1190000.00', '850000.00', '0.00', 0, '2 hours', '08:00', 'Da Nang city center', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/basket-boat-hoi-tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/basket-boat-hoi-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/my-son-sanctuary-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/ba-na-hills-tour-from-da-nang-600x400.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(103, 'Bach Ma National Park Tour From Da Nang', 'dananglocaltours-bach-ma-national-park-tour-from-da-nang-da-nang-local-tours', 2, 'Discover the breathtaking beauty of Bach Ma National Park on this guided tour from Da Nang. With its lush forests, stunning waterfalls, and diverse wildlife, this park is a nature lover''s paradise. Our expert guides will take you on a journey through the park''s most scenic trails, sharing their knowledge of the local flora and fauna. Enjoy a delicious lunch and immerse yourself in the local culture. This tour is perfect for those seeking an unforgettable adventure in central Vietnam.', 'Explore Bach Ma National Park', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Bach Ma National Park adventure."}, {"time": "09:00", "title": "Park Exploration", "description": "Start your journey through Bach Ma National Park, visiting the park''s highlights, including scenic viewpoints, hiking trails, and picturesque waterfalls."}, {"time": "12:00", "title": "Lunch Break", "description": "Enjoy a delicious lunch, either as part of our package or by exploring the local cuisine on your own, and take some time to rest and recharge."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue exploring the park, taking in the stunning scenery, capturing memorable photos, and learning about the local culture and history from our knowledgeable guides."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your unforgettable Bach Ma National Park tour."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour of Bach Ma National Park", "Lunch at a local restaurant", "Entrance fees to the national park"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Travel insurance"]'::jsonb, '1100000.00', '750000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-300x300.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/my-son-sanctuary-tour-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(104, 'Hoi An Basket Boat Tour From Da Nang', 'dananglocaltours-basket-boat-hoi-an-tour-from-da-nang-da-nang-local-tours', 2, 'Embark on a unique journey through Hoi An''s waterways on a traditional basket boat. This tour offers a glimpse into local life, rich history, and stunning natural beauty. From Da Nang, travel to Hoi An and experience the charm of this ancient town. Enjoy a day of exploration, cultural immersion, and relaxation in one of Vietnam''s most treasured destinations.', 'Explore Hoi An by basket boat', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Hoi An adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your Hoi An Basket Boat Tour by visiting the town''s iconic landmarks, including ancient temples, vibrant markets, and historic houses, each telling a story of Hoi An''s fascinating past."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy a delicious meal as part of our service package or opt to explore local cuisine on your own, followed by some leisure time to unwind and soak in the atmosphere."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration with a basket boat ride through the coconut groves, offering breathtaking views and insights into the local way of life. Capture memorable photos and learn about the area''s history and culture from our knowledgeable guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will return you to the initial meeting point, bringing to a close an unforgettable day in Hoi An, filled with unique experiences and lasting memories."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour in Hoi An", "Basket boat experience", "Lunch as per the service package", "Entrance fees to attractions"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any services not mentioned in the inclusions"]'::jsonb, '1075000.00', '750000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby in Da Nang', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/ba-na-hills-tour-from-da-nang-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/basket-boat-hoi-tour-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(105, 'Cham Island Snorkeling Tour From Da Nang', 'dananglocaltours-cham-island-snorkeling-tour-from-da-nang-good-price-1', 2, 'Explore the vibrant marine life of Cham Island on this guided snorkeling tour from Da Nang. With its crystal-clear waters and diverse coral reefs, Cham Island is a snorkeler''s paradise. Our expert guides will take you to the best spots to see an array of fish species, colorful coral, and other marine creatures. Enjoy a day of swimming, snorkeling, and relaxing on the beach, with all equipment and transportation provided.', 'Snorkel in Cham Island', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Cham Island adventure."}, {"time": "09:00", "title": "Island Tour", "description": "Start your Cham Island Snorkeling Tour with visits to the island''s main attractions, including its stunning beaches, scenic viewpoints, and historic landmarks."}, {"time": "12:00", "title": "Lunch Break", "description": "Enjoy a delicious lunch as part of your package or explore the local cuisine at your own pace, giving you a chance to recharge for the rest of the day."}, {"time": "15:00", "title": "Snorkeling and Relaxation", "description": "Spend the afternoon snorkeling in the island''s crystal-clear waters, exploring the underwater world, and relaxing on the beach, with ample time for photography and learning about the local culture."}, {"time": "17:30", "title": "Return", "description": "Our guide will escort you back to the initial meeting point, concluding your memorable Cham Island Snorkeling Tour From Da Nang experience."}]'::jsonb, '["Round-trip transportation from Da Nang", "Snorkeling equipment", "Guided tour", "Lunch", "Entrance fees to attractions"]'::jsonb, '["Personal expenses", "Tips for the guide", "Travel insurance"]'::jsonb, '1125000.00', '800000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/cham-island-snorkeling-tour-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(106, 'Hoa Phu Thanh Waterfall Sliding Daily Tour', 'dananglocaltours-hoa-phu-thanh-waterfall-sliding-daily-tour-da-nang-local-tours', 1, 'Immerse yourself in the natural beauty of Hoa Phu Thanh waterfall on this daily tour. Discover the stunning scenery, experience the thrill of sliding down the waterfall, and learn about the local culture. With a knowledgeable guide, you''ll explore the area''s hidden gems and enjoy a delicious meal. This tour is perfect for adventure-seekers and nature lovers alike, offering a unique and unforgettable experience in Da Nang.', 'Explore Hoa Phu Thanh waterfall', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting journey to Hoa Phu Thanh waterfall."}, {"time": "09:00", "title": "Main Attraction", "description": "Start your Hoa Phu Thanh waterfall sliding adventure, exploring the breathtaking scenery and experiencing the thrill of sliding down the waterfall, all while being guided by our expert team."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy a delicious meal as part of our package or take the opportunity to freely experience the local cuisine, replenishing your energy for the rest of the adventure."}, {"time": "15:00", "title": "Additional Experience", "description": "Continue exploring, taking memorable photos, and learning about the local culture, as our guide provides insightful information about the area''s history and customs."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We''ll transport you back to the initial meeting point, bringing your Hoa Phu Thanh waterfall sliding daily tour to a close, filled with unforgettable memories of your time in Da Nang."}]'::jsonb, '["Round-trip transportation from the meeting point", "Guided tour of Hoa Phu Thanh waterfall", "Sliding down the waterfall experience", "Meal as part of the package or freedom to experience local cuisine", "Insightful commentary about the local culture and history"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '1150000.00', '800000.00', '0.00', 0, '1 ngày', '08:00', 'Confirmed location', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-300x300.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/ba-na-hills-tour-from-da-nang-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(107, 'Hue City Tour from Da Nang', 'dananglocaltours-basket-boat-hue-tour-from-da-nang-good-price-1-da-nang-local-tours', 2, 'Embark on a captivating journey from Da Nang to Hue, a city steeped in history and culture. This meticulously crafted tour allows you to delve into the imperial past of Vietnam, visiting iconic landmarks such as the Imperial Citadel, Thien Mu Pagoda, and the Tombs of the Emperors. With a blend of historical insights, breathtaking landscapes, and local cuisine, this tour promises an unforgettable experience. From the moment you step into Hue, you''ll be immersed in its unique blend of traditional and modern Vietnamese culture, making for a truly enriching adventure.', 'Explore Hue''s heritage', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our tour vehicle and guide will pick you up at the confirmed meeting point, ensuring a prompt start to your day."}, {"time": "09:00", "title": "Main Attractions", "description": "Begin your Hue tour by visiting the city''s most notable sites, including the Imperial City, a walled fortress and palace compound that once served as the imperial capital of Vietnam. Explore the majestic architecture, beautiful gardens, and significant historical artifacts within."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy a delicious meal as part of your tour package or opt to experience the local cuisine on your own. This break also provides an opportunity to rest and recharge before the afternoon''s activities."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Hue with visits to the serene Thien Mu Pagoda and the elaborate Tombs of the Emperors. These sites offer a glimpse into the spiritual and royal heritage of the city. You''ll also have the chance to take memorable photos and learn more about the local culture and history from your knowledgeable guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "After a fulfilling day of exploring Hue''s treasures, our tour concludes with a return trip to Da Nang, dropping you off at the initial meeting point."}]'::jsonb, '["Round-trip transportation from Da Nang to Hue", "Experienced English-speaking guide", "Entrance fees to all mentioned attractions", "Lunch at a local restaurant"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any services not mentioned in the itinerary"]'::jsonb, '1475000.00', '1050000.00', '0.00', 0, '1 ngày', '08:00', 'Hotel lobby in Da Nang', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/my-son-sanctuary-tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/my-son-sanctuary-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/cham-island-snorkeling-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-600x400.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(108, 'Marble Mountains and Hoi An Discovery Tour', 'dananglocaltours-basket-boat-marble-mountain-hoi-an-tour-good-price-1-da-nang-local-tours', 2, 'Embark on a fascinating journey to the iconic Marble Mountains and the ancient town of Hoi An. This tour offers a unique blend of natural beauty, cultural heritage, and historical significance. Discover the stunning marble caves, sculptures, and temples, and wander through the charming streets of Hoi An, exploring its well-preserved architecture, vibrant markets, and delicious local cuisine. With a knowledgeable guide, you''ll uncover the secrets and stories behind these incredible destinations, creating unforgettable memories of your Vietnamese adventure.', 'Explore Marble Mountains and Hoi An', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting Marble Mountains and Hoi An tour."}, {"time": "09:00", "title": "Marble Mountains Exploration", "description": "Start your day by exploring the breathtaking Marble Mountains, where you''ll discover stunning caves, intricate sculptures, and beautiful temples, each with its own unique story and significance."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy a delicious meal, either as part of our package or by exploring the local culinary scene on your own. This is a great opportunity to rest and recharge for the rest of your adventure."}, {"time": "15:00", "title": "Hoi An Ancient Town Visit", "description": "Continue your journey in the ancient town of Hoi An, where you''ll have the chance to explore its vibrant markets, try local street food, and visit historic landmarks, all while learning about the town''s rich history and cultural heritage."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the day comes to a close, our guide will escort you back to the initial meeting point, bringing an end to your memorable Marble Mountains and Hoi An tour."}]'::jsonb, '["Round-trip transportation from the meeting point", "Experienced English-speaking guide", "Entrance fees to Marble Mountains and Hoi An Ancient Town", "Lunch at a local restaurant", "Bottled water throughout the tour"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any additional activities or services not mentioned in the itinerary"]'::jsonb, '975000.00', '700000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby or designated spot', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/basket-boat-hoi-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/cham-island-snorkeling-tour-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(109, 'My Son Sanctuary Tour From Da Nang', 'dananglocaltours-basket-boat-my-son-sanctuary-tour-from-da-nang-da-nang-local-tours', 2, 'Embark on a fascinating journey to the ancient My Son Sanctuary, a UNESCO World Heritage Site, and discover the rich history and culture of the Champa Kingdom. This guided tour from Da Nang takes you through the stunning landscapes and architectural wonders of the sanctuary, providing a unique and unforgettable experience. With a knowledgeable guide, you''ll delve into the significance of the site and learn about the daily life and traditions of the local people. Enjoy a delicious lunch and take part in exciting activities that showcase the region''s vibrant culture.', 'Explore ancient My Son Sanctuary', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your My Son Sanctuary adventure."}, {"time": "09:00", "title": "Sanctuary Exploration", "description": "Start your journey through the My Son Sanctuary, exploring the main attractions and learning about the history and significance of the site from your knowledgeable guide."}, {"time": "12:00", "title": "Lunch Break", "description": "Enjoy a delicious lunch, either as part of the package or by exploring the local cuisine on your own, and take some time to rest and recharge."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour, taking in the breathtaking views, capturing memorable photos, and gaining insight into the local culture and traditions from your guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your captivating My Son Sanctuary tour."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour of My Son Sanctuary", "Lunch as per the package details", "Entrance fees to the sanctuary", "Knowledgeable guide throughout the tour"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '1025000.00', '700000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby or designated point', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/ba-na-hills-tour-from-da-nang-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/ba-na-hills-tour-from-da-nang-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/my-son-sanctuary-tour-600x400.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(110, 'Than Tai Hot Spring Park Tour From Da Nang', 'dananglocaltours-basket-boat-nui-than-tai-hot-spring-park-tour-from-da-nang-good-price-1', 2, 'Embark on a rejuvenating journey to Than Tai Hot Spring Park, nestled in the picturesque landscapes of Da Nang. This comprehensive tour offers a unique blend of natural beauty, cultural experiences, and relaxation. Guests will have the opportunity to unwind in the park''s soothing hot springs, explore the surrounding area, and indulge in local cuisine. With a carefully curated itinerary, this tour promises an unforgettable experience for travelers seeking to escape the hustle and bustle of city life.', 'Explore Than Tai Hot Spring Park', '[{"time": "07:30", "title": "Pickup", "description": "Guests will be picked up from the designated meeting point by our experienced guide and driver, marking the beginning of an exciting adventure to Than Tai Hot Spring Park."}, {"time": "09:00", "title": "Park Exploration", "description": "Upon arrival, guests will commence their exploration of the park, discovering its stunning natural beauty, including the hot springs, and learning about the local flora and fauna."}, {"time": "12:00", "title": "Lunch Break", "description": "Guests will enjoy a delectable lunch, either as part of the tour package or by exploring the local culinary scene, allowing them to recharge for the afternoon''s activities."}, {"time": "15:00", "title": "Cultural Immersion", "description": "The afternoon will be filled with cultural experiences, including visits to local landmarks, photography opportunities, and insightful introductions to the region''s rich heritage."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the day draws to a close, guests will be escorted back to the original meeting point, bringing an end to a memorable and enriching experience at Than Tai Hot Spring Park."}]'::jsonb, '["Round-trip transportation from Da Nang", "Admission to Than Tai Hot Spring Park", "Guided tour with a knowledgeable and experienced guide", "Lunch as per the tour package or option to explore local cuisine", "Cultural experiences and activities"]'::jsonb, '["Personal expenses and souvenirs", "Optional activities not included in the tour package", "Travel insurance"]'::jsonb, '1225000.00', '850000.00', '0.00', 0, '1 ngày', '08:00', 'Hotel lobby or designated point', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/cham-island-snorkeling-tour-300x300.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(111, 'Son Tra Peninsula, Marble Mountains & Hoi An Daily Tour', 'dananglocaltours-basket-boat-son-tra-peninsula-marble-mountains-hoian-daily-tour', 2, 'Embark on a captivating journey through Vietnam''s stunning landscapes and rich cultural heritage. This daily tour takes you to the breathtaking Son Tra Peninsula, the majestic Marble Mountains, and the ancient town of Hoi An. With its unique blend of natural beauty, historical significance, and local charm, this tour promises an unforgettable experience. From the panoramic views of the peninsula to the intricate marble carvings and the quaint streets of Hoi An, every moment is a discovery. Whether you''re a nature lover, a history enthusiast, or simply a traveler seeking new experiences, this tour has something for everyone.', 'Explore Son Tra, Marble Mountains & Hoi An', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting journey."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your Son Tra Peninsula, Marble Mountains, and Hoi An tour by visiting the key attractions included in the program. This segment of the tour is designed to give you a comprehensive overview of the area''s most notable landmarks."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the service package or take the opportunity to explore and experience the local cuisine at your own pace. This break is designed to refresh and recharge you for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration with more visits, photo opportunities, and insights into the local culture. This part of the tour is tailored to deepen your understanding and appreciation of the region''s unique characteristics."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will return you to the initial meeting point, bringing the tour to a close. This final leg of the journey gives you a chance to reflect on the day''s adventures and the memories you''ve made."}]'::jsonb, '["Round-trip transportation from the meeting point", "Guided tour of Son Tra Peninsula, Marble Mountains, and Hoi An", "Lunch as per the service package", "Entry fees for all attractions mentioned in the itinerary", "Professional guide services throughout the tour"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any meals or drinks not specified in the itinerary", "Travel insurance"]'::jsonb, '1175000.00', '800000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby or a designated spot', 30, 1, NULL, NULL, 'https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg', '["https://dananglocaltours.com/wp-content/uploads/2019/12/Bach-Ma-National-Park-Tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hoa-phu-thanh-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/nui-than-tai-spring-park-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/marble-mountain-hoi-an-tour-100x100.jpg", "https://dananglocaltours.com/wp-content/uploads/2020/02/son-tra-peninsula-600x400.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/hue-tour-from-da-nang-300x300.jpg", "https://dananglocaltours.com/wp-content/uploads/2019/12/cham-island-snorkeling-tour-300x300.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(112, 'French Village Ba Na Hills Tour', 'danangtourscity-french-village-ba-na-hills-da-nang-tours', 1, 'Embark on a captivating journey to French Village Ba Na Hills, a mesmerizing destination near Da Nang. This tour offers a unique blend of French and Vietnamese cultures, breathtaking scenery, and thrilling experiences. Guests will have the opportunity to explore the village''s charming architecture, visit notable landmarks, and indulge in local cuisine. With its rich history and stunning natural beauty, French Village Ba Na Hills is an ideal destination for travelers seeking a distinctive and unforgettable experience.', 'Explore French Village in Ba Na Hills', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your French Village Ba Na Hills adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Commence your journey through the highlights of French Village Ba Na Hills, including its iconic landmarks, scenic views, and cultural exhibits, showcasing the unique heritage of the area."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the tour package or opt to explore local eateries on your own, savoring the flavors of the region. This break also provides an opportunity to relax and recharge for the rest of the day''s activities."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of French Village, capturing memorable photos and learning about the local customs and traditions from our knowledgeable guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, bringing your French Village Ba Na Hills tour to a close, filled with unforgettable moments and experiences."}]'::jsonb, '["Round-trip transportation from the meeting point", "Guided tour of French Village Ba Na Hills", "Lunch as per the tour package", "Admission fees to attractions and landmarks"]'::jsonb, '["Personal expenses and souvenirs", "Optional activities not included in the tour package", "Tips for the guide and driver"]'::jsonb, '1090000.00', '750000.00', '0.00', 0, '2 hours', '08:00', 'Hotel lobby or designated point', 30, 1, NULL, NULL, 'https://danangtourscity.com/wp-content/uploads/2023/06/da-nang-tours.png', '["https://danangtourscity.com/wp-content/uploads/2023/06/da-nang-tours.png", "https://danangtourscity.com/wp-content/uploads/2023/06/french-village-ba-na-hills.jpg", "https://danangtourscity.com/wp-content/uploads/2023/06/ba-na-hills-wax-museum.jpg", "https://danangtourscity.com/wp-content/uploads/2023/06/da-nang-beach.jpg", "https://danangtourscity.com/wp-content/uploads/2023/07/nha-trang-beaches.jpg", "https://danangtourscity.com/wp-content/uploads/2023/07/travel-to-vietnam-from-canada.jpg", "https://danangtourscity.com/wp-content/uploads/2023/07/vietnam-e-visa.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(113, 'Am Phu Cave and Marble Mountains Tour with Lady Buddha', 'hoiandaytrip-am-phu-cave-tour-with-marble-mountain-lady-buddha-hoian-day-trip-company', 1, 'Embark on a fascinating journey to the Am Phu Cave, Marble Mountains, and the iconic Lady Buddha. This day trip from Hoi An offers a unique blend of natural beauty, cultural significance, and historical importance. Discover the stunning landscapes, intricate caves, and majestic marble structures that make this region a must-visit destination. With a knowledgeable guide, delve into the local history, mythology, and traditions that surround these incredible sites. Enjoy a delicious meal, take breathtaking photos, and create unforgettable memories in this captivating corner of Vietnam.', 'Explore caves and mountains', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your Am Phu Cave Tour with Marble Mountain and Lady Buddha, exploring the highlights of the program, including the majestic caves, mountains, and the revered Lady Buddha statue."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the service package or take the opportunity to experience the local cuisine at your own pace, replenishing your energy for the afternoon''s activities."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour, capturing memorable photos and listening to insightful introductions about the local culture, history, and legends that enrich the beauty of the sites you visit."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your tour, filled with unforgettable experiences and memories of the Am Phu Cave, Marble Mountains, and the Lady Buddha."}]'::jsonb, '["Round-trip transportation from the meeting point", "Experienced guide throughout the tour", "Admission fees to Am Phu Cave and Marble Mountains", "Visit to the Lady Buddha", "Lunch as per the service package"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '1125000.00', '800000.00', '0.00', 0, '4 giờ', '08:00', 'Hotel lobby or designated point', 30, 1, NULL, NULL, 'https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png', '["https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-154.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-137.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-120-scaled.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-116.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-110-scaled.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-106.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/tour-photo-101.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(114, 'Ba Na Hills Afternoon Tour with Golden Bridge', 'hoiandaytrip-ba-na-hills-afternoon-tour-with-golden-hands-bridge-hoian-day-trip-company', 1, 'Embark on an unforgettable journey to Ba Na Hills, where breathtaking scenery and stunning architecture await. This afternoon tour takes you to the iconic Golden Bridge, offering panoramic views of the surrounding landscape. With a rich history and vibrant culture, Ba Na Hills is a must-visit destination for any traveler. Our expert guides will lead you through the hills, sharing insights into the local way of life and the significance of the Golden Bridge. Enjoy a delicious meal, take in the stunning vistas, and create unforgettable memories on this incredible tour.', 'Explore Ba Na Hills', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Ba Na Hills adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your Ba Na Hills Afternoon Tour with a visit to the most notable landmarks, including the Golden Bridge, and immerse yourself in the local culture and history."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy a meal as part of our package or explore the local cuisine at your own pace, replenishing your energy for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Ba Na Hills, capturing memorable photos and learning about the local customs and traditions from our knowledgeable guides."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your Ba Na Hills Afternoon Tour with unforgettable memories of the Golden Bridge and beyond."}]'::jsonb, '["Round-trip transportation from the meeting point", "Expert guide services throughout the tour", "Access to the Golden Bridge and other main attractions", "Meal as per the package details"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '2125000.00', '1500000.00', '0.00', 0, '5 giờ', '08:00', 'Hotel lobby', 30, 1, NULL, NULL, 'https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png', '["https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-cable-car-1-1-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2025/01/golden-bridge-vietnam-photo-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/le-jardin-damour-flower-garden-ba-na-hills-14-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/buddha-statue-ba-na-hills-vietnam-9-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/linh-ung-pagoda-ba-na-hills-1-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/saint-denis-church-ba-na-hills-4-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-brewery-1-5-768x512.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(115, 'Ba Na Hills Early Morning Tour', 'hoiandaytrip-bana-ba-na-hills-early-morning-tour-to-beat-the-crowds-hoian-day-trip-company', 1, 'Embark on an early morning adventure to Ba Na Hills, a stunning destination known for its breathtaking scenery and unique attractions. This carefully crafted tour allows you to experience the best of Ba Na Hills before the crowds arrive, ensuring a more intimate and immersive experience. With a focus on exploration and discovery, this tour is perfect for those seeking to uncover the hidden gems of this incredible location. From the moment you step foot in Ba Na Hills, you''ll be treated to a world of natural beauty, rich culture, and unforgettable moments.', 'Beat the crowds in Ba Na Hills', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our tour vehicle and experienced guide will collect you from the designated meeting point, marking the beginning of your Ba Na Hills Early Morning Tour. This is a great opportunity to get acquainted with your fellow travelers and prepare for the exciting day ahead."}, {"time": "09:00", "title": "Exploring Ba Na Hills", "description": "Commence your journey through Ba Na Hills, visiting the most notable attractions and landmarks. Our knowledgeable guide will provide insightful commentary, sharing the history, culture, and significance of each location, allowing you to gain a deeper understanding and appreciation of this remarkable destination."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and indulge in a delicious meal, either as part of our tour package or by exploring the local cuisine at your own leisure. This is a great chance to recharge and reflect on the morning''s adventures, while also looking forward to the exciting experiences that the afternoon has in store."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Ba Na Hills, capturing memorable photographs and learning about the local culture and customs. Our guide will be on hand to answer any questions and provide further insights, ensuring that you make the most of your time in this incredible location."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the day draws to a close, our tour vehicle will transport you back to the original meeting point, marking the end of your Ba Na Hills Early Morning Tour. This is a great opportunity to reflect on the day''s experiences and share stories with your fellow travelers, while also looking forward to the memories that will last a lifetime."}]'::jsonb, '["Round-trip transportation from the designated meeting point", "Experienced guide with extensive knowledge of Ba Na Hills", "Admission to all attractions and landmarks", "Delicious meal as part of the tour package or freedom to explore local cuisine"]'::jsonb, '["Personal expenses and souvenirs", "Optional activities and experiences not included in the tour package", "Travel insurance and other related costs"]'::jsonb, '2125000.00', '1500000.00', '0.00', 0, '5 giờ', '08:00', 'Hotel lobby or designated location', 30, 1, NULL, NULL, 'https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png', '["https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-cable-car-1-1-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2025/01/golden-bridge-vietnam-photo-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/le-jardin-damour-flower-garden-ba-na-hills-5-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/buddha-statue-ba-na-hills-vietnam-9-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/linh-ung-pagoda-ba-na-hills-1-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/saint-denis-church-ba-na-hills-4-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-brewery-1-9-768x512.jpg"]'::jsonb, NULL, 'inactive', 'open', false, f