(116, 'Ba Na Hills Night Tour with Golden Bridge, Dinner & Cabaret Show', 'hoiandaytrip-bana-ba-na-hills-night-tour-with-golden-bridge-dinner-cabaret-show-hoian-day-trip-company', 1, 'Experience the breathtaking beauty of Ba Na Hills under the stars. This night tour includes a visit to the iconic Golden Bridge, a delicious dinner, and a spectacular cabaret show. With its stunning landscapes and exciting entertainment, this tour is perfect for those seeking a unique and unforgettable experience in Vietnam. From the moment you step into the hills, you''ll be immersed in a world of natural wonder and cultural richness, making for an evening that will leave you with lasting memories.', 'Explore Ba Na Hills at night', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Ba Na Hills adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Commence your Ba Na Hills Night Tour, exploring the key attractions including the Golden Bridge, where you can marvel at its grandeur and take in the panoramic views of the surrounding landscape."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the tour package or opt to experience the local cuisine on your own, taking some time to rest and recharge for the exciting activities ahead."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your journey with more sightseeing, capturing memorable photos, and learning about the local culture through insightful introductions by your guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will return you to the initial meeting point, bringing your Ba Na Hills Night Tour to a close, filled with unforgettable moments and experiences."}, {"time": "19:00", "title": "Dinner", "description": "Savor a delicious dinner at a local restaurant, enjoying the flavors of Vietnamese cuisine."}, {"time": "20:30", "title": "Cabaret Show", "description": "Be mesmerized by a spectacular cabaret show, featuring talented performers and a blend of music, dance, and drama."}]'::jsonb, '["Round-trip transportation from the meeting point", "Admission to Ba Na Hills and the Golden Bridge", "Dinner at a local restaurant", "Cabaret show ticket", "Guided tour with English-speaking guide"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '2200000.00', '1550000.00', '0.00', 0, '6 giờ', '14:00', 'Hotel lobby', 30, 1, NULL, NULL, 'https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png', '["https://hoiandaytrip.com/wp-content/uploads/2024/10/Asset-1@4x.png", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-cable-car-ride-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2025/01/golden-bridge-vietnam-photo-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/le-jardin-damour-flower-garden-ba-na-hills-5-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/buddha-statue-ba-na-hills-vietnam-9-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/linh-ung-pagoda-ba-na-hills-1-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/french-village-ba-na-hills-17-768x512.jpg", "https://hoiandaytrip.com/wp-content/uploads/2024/11/ba-na-hills-food-restaurants-10-768x512.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(117, 'From Da Nang: My Son Holy Land & Rice Paper Making Morning Tour', 'venus-cham-island-from-danang-my-son-holyland-rice-paper-making-morning-tour-venustravel', 2, 'Embark on a morning tour from Da Nang to My Son Holy Land, a UNESCO World Heritage Site, and experience the art of traditional rice paper making. Discover the ancient Cham ruins, learn about the history and culture of the region, and enjoy a unique opportunity to engage with local artisans. This tour offers a blend of history, culture, and hands-on experience, making it a must-do for anyone visiting central Vietnam.', 'Explore My Son Holy Land', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting journey to My Son Holy Land and a traditional rice paper making experience."}, {"time": "09:00", "title": "My Son Holy Land Tour", "description": "Start your exploration of My Son Holy Land, a complex of ancient temples built by the Cham civilization. Our knowledgeable guide will provide insights into the history and significance of these ruins, helping you understand the cultural and historical context of the site."}, {"time": "11:30", "title": "Rice Paper Making Experience", "description": "Visit a local village to learn the traditional art of rice paper making. Engage with local artisans and participate in the process, from preparing the ingredients to crafting your own rice paper products. This hands-on experience offers a unique glimpse into Vietnamese culture and daily life."}, {"time": "12:30", "title": "Lunch Break", "description": "Enjoy a delicious lunch, either as part of our package or by exploring local cuisine on your own. This break provides an opportunity to rest and recharge before continuing your tour."}, {"time": "14:00", "title": "Additional Exploration", "description": "Continue your tour with more exploration, photography opportunities, and learning about local customs and traditions. Our guide will ensure that you make the most of your time, providing detailed information and answering any questions you may have."}, {"time": "17:00", "title": "Return to Da Nang", "description": "After a fulfilling day, we will transport you back to the meeting point in Da Nang, bringing your My Son Holy Land and rice paper making morning tour to a close."}]'::jsonb, '["Round-trip transportation from Da Nang", "Guided tour of My Son Holy Land", "Rice paper making experience with local artisans", "Lunch as per the package details", "English-speaking guide"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any services not mentioned in the inclusions"]'::jsonb, '775250.00', '550000.00', '0.00', 0, 'Half Day', '08:00', 'Confirmed pickup point', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(118, 'Hoi An City Tour, Boat Ride & Flower Lantern Release', 'venus-cham-island-hoi-an-city-tour-boat-ride-release-flower-lantern-venustravel', 2, 'Discover the charm of Hoi An city with a guided tour, boat ride, and flower lantern release. Visit iconic landmarks, experience local culture, and enjoy a relaxing boat ride along the river. The tour includes a delicious meal, allowing you to savor the local flavors. As the sun sets, release flower lanterns on the water, creating a magical atmosphere. This tour is a perfect blend of history, culture, and natural beauty, making it an unforgettable experience in Hoi An.', 'Explore Hoi An city', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Hoi An city tour adventure."}, {"time": "09:00", "title": "City Tour", "description": "Embark on a journey to explore Hoi An''s iconic landmarks, including ancient temples, historic houses, and vibrant local markets, showcasing the city''s rich cultural heritage."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Enjoy a delicious meal as part of our package or take the opportunity to experience the local cuisine at your own pace, followed by some relaxation time to recharge for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Hoi An, capturing memorable photos and learning about the local customs and traditions from our knowledgeable guide."}, {"time": "17:30", "title": "Boat Ride and Lantern Release", "description": "Experience a serene boat ride along the river, culminating in the magical release of flower lanterns on the water, a truly enchanting experience as the day comes to a close."}, {"time": "18:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your Hoi An city tour, boat ride, and flower lantern release experience."}]'::jsonb, '["Guided tour of Hoi An city", "Boat ride along the river", "Flower lantern release experience", "Meal as per the package", "Knowledgeable guide throughout the tour"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '641250.00', '450000.00', '0.00', 0, 'Half Day', '08:00', 'Hotel lobby', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(119, 'Marble Mountains, Monkey Mountain & Am Phu Cave Morning Tour', 'venus-cham-island-marble-mountains-monkey-mountain-am-phu-cave-morning-tour-venustravel', 2, 'Embark on a fascinating morning tour to discover the natural beauty and cultural significance of Marble Mountains, Monkey Mountain, and Am Phu Cave. This guided tour offers a unique blend of stunning landscapes, ancient temples, and captivating local stories. With a carefully crafted itinerary, you''ll have the opportunity to immerse yourself in the local culture, take breathtaking photos, and create unforgettable memories. From the majestic marble structures to the lush forests of Monkey Mountain, every moment of this tour promises to be an exciting adventure.', 'Explore Marble Mountains, Monkey Mountain & Am Phu Cave', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our tour vehicle and guide will pick you up at the confirmed meeting point, ensuring a prompt start to your exciting journey."}, {"time": "09:00", "title": "Main Tour Attractions", "description": "Begin your Marble Mountains, Monkey Mountain, and Am Phu Cave Morning Tour by exploring the key attractions, each offering a glimpse into the region''s rich history and natural splendor."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Enjoy a meal as part of our service package or take the opportunity to experience local cuisine at your own pace, replenishing your energy for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour with more sightseeing, photography opportunities, and insightful introductions to the local culture, ensuring a comprehensive and engaging experience."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of a memorable and enriching tour experience."}]'::jsonb, '["Round-trip transportation from the meeting point", "Guided tour service", "Admission fees to Marble Mountains, Monkey Mountain, and Am Phu Cave", "Meal as per the service package"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any additional activities not mentioned in the itinerary"]'::jsonb, '603000.00', '400000.00', '0.00', 0, 'Half Day', '08:00', 'Hotel lobby or designated point', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(120, 'Marble Mountains, Monkey Mountain & Am Phu Cave Sunset Tour', 'venus-cham-island-marble-mountains-monkey-mountain-am-phu-cave-sunset-tour-venustravel', 2, 'Embark on a captivating journey to Marble Mountains, Monkey Mountain, and Am Phu Cave, where breathtaking sunsets and stunning landscapes await. This tour offers a unique blend of natural beauty, cultural experiences, and thrilling adventures. From the majestic marble structures to the lush forests of Monkey Mountain, every moment is a testament to the region''s rich heritage and diverse ecosystems. As the day unfolds, witness the sky painted with hues of gold and crimson during the sunset at Am Phu Cave, a truly unforgettable experience.', 'Explore Marble Mountains & Monkey Mountain', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting tour."}, {"time": "09:00", "title": "Main Attractions Tour", "description": "Commence your Marble Mountains, Monkey Mountain, and Am Phu Cave Sunset Tour, exploring the most notable sites and landmarks included in the program."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the service package or take the opportunity to experience local cuisine at your leisure."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour with visits to more attractions, capture memorable photos, and gain insights into the local culture through our guide''s presentations."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will return you to the initial meeting point, bringing the program to a close."}]'::jsonb, '["Round-trip transportation from the meeting point", "Experienced guide throughout the tour", "Admission fees to Marble Mountains, Monkey Mountain, and Am Phu Cave", "Lunch as per the service package"]'::jsonb, '["Personal expenses and souvenirs", "Tips for the guide and driver", "Any services not mentioned in the inclusions"]'::jsonb, '545500.00', '400000.00', '0.00', 0, 'Half Day', '14:00', 'Hotel lobby or a designated spot', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(121, 'Three Traditional Handicraft Villages Tour', 'venusvietnamtravel-3-traditional-handicraft-villages-in-1-tour-venustravel', 2, 'Immerse yourself in the rich cultural heritage of traditional handicraft villages. This tour takes you on a journey to three unique villages, each specializing in a distinct craft. From woodcarvings to textiles, and pottery, discover the skills and techniques that have been passed down through generations. With a knowledgeable guide, delve into the history and significance of each craft, and witness the artisans at work. This comprehensive tour offers a fascinating insight into the traditional practices and customs of these villages, allowing you to appreciate the beauty and craftsmanship of each handicraft.', 'Explore 3 villages in 1 tour', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, ensuring a prompt start to your tour."}, {"time": "09:00", "title": "Main Attraction Visit", "description": "Begin your journey through the three traditional handicraft villages, exploring the main attractions and landmarks that showcase the unique characteristics of each village."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy a meal as part of our service package or take the opportunity to experience the local cuisine at your own pace, replenishing your energy for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your tour with a deeper dive into the local culture, including photography opportunities and insightful commentary from your guide about the history and customs of the villages."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will return you to the initial meeting point, marking the end of your enriching journey through the three traditional handicraft villages."}]'::jsonb, '["Transportation to and from the meeting point", "Guided tour of the three traditional handicraft villages", "Lunch as part of the service package", "Opportunities for photography and cultural immersion"]'::jsonb, '["Personal expenses and souvenirs", "Additional meals or drinks not included in the package", "Optional activities or entrance fees not specified in the itinerary"]'::jsonb, '976250.00', '700000.00', '0.00', 0, 'Half Day', '08:00', 'Main city square', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(122, 'Afternoon Ba Na Hills, Golden Bridge & Dragon Bridge by Night', 'venusvietnamtravel-afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour-venustravel', 1, 'Embark on an unforgettable afternoon journey to Ba Na Hills, Golden Bridge, and Dragon Bridge. This tour offers breathtaking views, thrilling experiences, and insights into local culture. With a guided tour, you''ll discover the natural beauty of Ba Na Hills, walk across the iconic Golden Bridge, and marvel at the stunning Dragon Bridge. Enjoy a delicious meal, take memorable photos, and create lifelong memories in this enchanting destination.', 'Explore Ba Na Hills & Golden Bridge', '[{"time": "07:30", "title": "Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your exciting adventure."}, {"time": "09:00", "title": "Main Attractions", "description": "Start your journey with a visit to the main attractions in Ba Na Hills, including the Golden Bridge and Dragon Bridge, and enjoy the panoramic views of the surrounding landscape."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Take a break and indulge in a delicious meal, either as part of our package or by exploring local cuisine on your own, and recharge for the rest of the tour."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration, capturing stunning photos and learning about the local culture and history from our knowledgeable guide."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guide will escort you back to the initial meeting point, marking the end of your memorable afternoon tour."}]'::jsonb, '["Round-trip transportation", "Guided tour", "Admission fees to Ba Na Hills and Golden Bridge", "Delicious meal", "Opportunities for photography and cultural immersion"]'::jsonb, '["Personal expenses", "Tips for the guide and driver", "Any additional activities or services not mentioned in the itinerary"]'::jsonb, '1540750.00', '1100000.00', '0.00', 0, 'Half Day', '14:00', 'Hotel lobby or designated spot', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(123, 'Cam Thanh Coconut Jungle Muslim Tour', 'venusvietnamtravel-cam-thanh-coconut-jungle-muslim-tour-venustravel', 2, 'Immerse yourself in the serene beauty of Cam Thanh Coconut Jungle on this specially curated Muslim tour. Discover the local culture, savor delicious Halal cuisine, and unwind amidst the lush greenery of the coconut jungle. This tour offers a unique blend of natural wonders, cultural experiences, and spiritual rejuvenation, making it an ideal getaway for Muslim travelers. With its carefully crafted itinerary, this tour ensures a memorable and enriching experience for all participants.', 'Explore Cam Thanh''s coconut jungle', '[{"time": "07:30", "title": "Guest Pickup", "description": "Our vehicle and guide will pick you up at the confirmed meeting point, marking the beginning of your Cam Thanh Coconut Jungle Muslim Tour adventure."}, {"time": "09:00", "title": "Main Attraction Visit", "description": "Commence your journey through the highlights of the Cam Thanh Coconut Jungle Muslim Tour, exploring the key attractions and experiences that this unique tour has to offer."}, {"time": "12:00", "title": "Lunch and Rest", "description": "Enjoy your meal as part of the tour package or opt to explore the local culinary scene at your own pace, taking a moment to relax and recharge for the rest of the day''s adventures."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of the area, capturing memorable moments through photography, and gaining insight into the local culture and traditions from our knowledgeable guides."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We will escort you back to the initial meeting point, bringing to a close your captivating experience on the Cam Thanh Coconut Jungle Muslim Tour."}]'::jsonb, '["Round-trip transportation from the meeting point", "Guided tour of Cam Thanh Coconut Jungle", "Halal meal as specified in the tour package", "Admission fees to attractions included in the itinerary", "Services of an experienced and knowledgeable guide"]'::jsonb, '["Personal expenses and souvenirs", "Optional activities not mentioned in the itinerary", "Travel insurance", "Tips for the guide and driver"]'::jsonb, '1225000.00', '850000.00', '0.00', 0, '2 ngày', '08:00', 'Hotel lobby or designated spot', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/z4382853390974_ab7cda7de7c863e94bcbae0763309da8.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/image-78.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/z5647624863077_04fb816caaa68e91f30e39583d9af9de.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/z5494714869104_11be793aec9da91b7d19cc1ce259bcd7.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/sapa-muslimtour.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/07/z5647624793494_53f9b26b1ef5609df98ba59d98daae47.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(124, 'Cam Thanh Cooking Class and My Son Holy Land Full-Day Tour', 'venusvietnamtravel-cam-thanh-cooking-class-my-son-holy-land-full-day-tour-venustravel', 2, 'Join us on a full-day adventure to Cam Thanh and My Son, two of Vietnam''s most fascinating destinations. Begin with a cooking class in Cam Thanh, where you''ll learn the art of traditional Vietnamese cuisine from a local chef. Discover the secrets of fresh ingredients, aromatic spices, and expert techniques that make Vietnamese food so beloved around the world. After a delicious lunch, head to My Son, a UNESCO World Heritage Site and ancient Cham temple complex. Explore the stunning ruins, learn about the history and mythology of the Cham people, and marvel at the intricate carvings and architecture. This tour is a unique blend of culture, history, and cuisine that will leave you with unforgettable memories of Vietnam.', 'Immerse yourself in the rich culture of Vietnam with a cooking class and historical tour.', '[{"time": "07:30", "title": "Morning Pickup", "description": "Our friendly guide will meet you at your hotel and escort you to the tour vehicle, where you''ll begin your journey to Cam Thanh and My Son."}, {"time": "09:00", "title": "Cam Thanh Cooking Class", "description": "Arrive at the Cam Thanh Cooking School, where you''ll be greeted by your local chef instructor. Learn the art of traditional Vietnamese cuisine, from preparing fresh ingredients to cooking delicious dishes. Enjoy the fruits of your labor over a delicious lunch."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy the lunch you prepared during the cooking class. Relax and recharge for the afternoon ahead."}, {"time": "15:00", "title": "My Son Holy Land Tour", "description": "Visit the ancient Cham temple complex of My Son, a UNESCO World Heritage Site. Explore the stunning ruins, learn about the history and mythology of the Cham people, and marvel at the intricate carvings and architecture."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Return to your hotel, reflecting on the unforgettable experiences and memories you''ve made during the Cam Thanh Cooking Class and My Son Holy Land Full-Day Tour."}]'::jsonb, '["Round-trip transportation from your hotel", "Expert local guide", "Cam Thanh Cooking Class with lunch", "My Son Holy Land Tour", "All entrance fees and activities"]'::jsonb, '["Personal expenses and gratuities", "Travel insurance"]'::jsonb, '1215500.00', '850000.00', '0.00', 0, 'Half Day', '08:00', 'Please meet your guide at your hotel lobby at 07:30 AM, ready to begin your adventure.', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(125, 'Cam Thanh Eco Tour & My Son Holy Land Tour', 'venusvietnamtravel-cam-thanh-eco-tour-my-son-holy-land-full-day-tour-venustravel', 2, 'Embark on a full-day adventure through the lush countryside and ancient ruins of Central Vietnam. This tour combines the tranquil beauty of Cam Thanh Eco Tour with the historical significance of My Son Holy Land, offering a unique and enriching experience for travelers. Discover the region''s rich cultural heritage, immerse yourself in the local way of life, and create unforgettable memories.', 'Explore the natural beauty and cultural heritage of Central Vietnam', '[{"time": "07:30", "title": "Tour Commencement", "description": "Meet your guide and driver at the designated meeting point, where you''ll begin your journey through the picturesque countryside of Central Vietnam. Enjoy a scenic drive to the first destination, setting the tone for a day filled with natural beauty and cultural significance."}, {"time": "09:00", "title": "Cam Thanh Eco Tour", "description": "Arrive at Cam Thanh Eco Tour, a serene and tranquil oasis nestled among the lush greenery of the countryside. Take a boat ride through the tranquil waterways, observing the local wildlife and learning about the region''s unique ecosystem. This is an opportunity to disconnect from the hustle and bustle of city life and reconnect with nature."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break for lunch at a local restaurant, where you can indulge in traditional Vietnamese cuisine and refresh yourself for the afternoon ahead. Alternatively, you may choose to explore the surrounding area, immersing yourself in the local way of life and interacting with the friendly locals."}, {"time": "15:00", "title": "My Son Holy Land", "description": "Visit the ancient ruins of My Son Holy Land, a UNESCO World Heritage Site and one of Vietnam''s most significant cultural attractions. Explore the intricate temples and learn about the history and mythology behind this sacred site. This is a chance to delve into the region''s rich cultural heritage and appreciate the beauty of ancient architecture."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the day draws to a close, your guide and driver will escort you back to the meeting point, marking the end of an unforgettable adventure through the natural beauty and cultural heritage of Central Vietnam. Reflect on the experiences and memories you''ve created, and depart with a newfound appreciation for this enchanting region."}]'::jsonb, '["English-speaking guide", "Air-conditioned vehicle", "Lunch at a local restaurant", "Boat ride through Cam Thanh Eco Tour", "Entrance fees to My Son Holy Land"]'::jsonb, '["Personal expenses", "Tips and gratuities", "Travel insurance"]'::jsonb, '1215500.00', '850000.00', '0.00', 0, 'Half Day', '08:00', 'Meet at the hotel lobby or a designated meeting point in Hoi An city center at 07:30 AM sharp.', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(126, 'Cham Island Sightseeing and Snorkeling Adventure', 'venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel', 2, 'Embark on a captivating journey to the Cham Islands, a tranquil archipelago located off the coast of Central Vietnam. This enchanting tour offers a unique blend of culture, history, and natural beauty, perfect for those seeking an unforgettable experience. As we set sail, you''ll be treated to breathtaking views of the surrounding islands and the opportunity to snorkel in the crystal-clear waters, teeming with an array of marine life. Visit the island''s picturesque villages, explore the ancient Cham ruins, and indulge in the local cuisine, all while soaking up the warm hospitality of the islanders. Whether you''re a history buff, a nature lover, or simply looking for a relaxing getaway, this tour has something for everyone.', 'Explore the stunning Cham Islands and discover their hidden treasures.', '[{"time": "07:30", "title": "Morning Pickup", "description": "Our friendly guide will meet you at your designated pickup point, where you''ll board our comfortable vehicle for the journey to the Cham Islands."}, {"time": "09:00", "title": "Explore the Island''s Main Attractions", "description": "Begin your island adventure with a visit to the island''s main points of interest, including ancient Cham ruins, picturesque villages, and stunning beaches."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy a delicious meal at a local restaurant, or simply relax on the beach and soak up the sun."}, {"time": "15:00", "title": "Additional Activities", "description": "Continue your exploration of the island, taking part in additional activities such as snorkeling, swimming, or simply taking in the breathtaking views."}, {"time": "17:30", "title": "Tour Conclusion", "description": "After a day filled with adventure and discovery, our guide will escort you back to your pickup point, marking the end of your Cham Island Sightseeing and Snorkeling Adventure."}]'::jsonb, '["Round-trip transportation from your designated pickup point", "English-speaking guide", "Lunch at a local restaurant", "Snorkeling equipment", "Island entrance fees"]'::jsonb, '["Additional food and drink", "Personal expenses", "Travel insurance"]'::jsonb, '765750.00', '550000.00', '0.00', 0, 'Half Day', '08:00', 'Please meet your guide at your designated pickup point, located at the Da Nang Marina, 15 minutes prior to the scheduled departure time.', 30, 1, NULL, NULL, 'https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png', '["https://static.tacdn.com/img2/travelers_choice/widgets/tchotel_2025_L.png", "https://www.tripadvisor.com.vn/img/cdsi/img2/branding/v2/Tripadvisor_lockup_horizontal_secondary_registered-18034-2.svg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/z7824261136076_79df93aa2867fca757d86e48af8eb7ae.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/04/Anh-OTA-2.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2023/11/Anh-OTA-3.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2024/01/Anh-OTA-2.png", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/07/ba.jpg", "https://venus-cdn.b-cdn.net/wp-content/uploads/2022/06/z7807772830058_b599b5aa89ee9ecafb6964525e72db45.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(127, 'Da Nang Shore Excursions from Tien Sa Port: Deluxe Tours', 'vmtravel-da-nang-shore-excursions-from-tien-sa-port-deluxe-tours', 1, 'Embark on a captivating journey through Da Nang, a coastal city in central Vietnam, known for its rich history, pristine beaches, and vibrant culture. This guided shore excursion is carefully crafted to provide an unforgettable experience for cruise passengers docking at Tien Sa Port. Our expert guide will lead you through a carefully curated itinerary, showcasing the city''s most iconic landmarks, cultural attractions, and hidden gems. From the moment you step off the ship, you''ll be immersed in the sights, sounds, and flavors of Da Nang, creating lifelong memories of your time in this enchanting city.', 'Experience Da Nang''s vibrant culture and stunning landscapes on this guided shore excursion.', '[{"time": "07:30", "title": "Meet and Greet", "description": "Your driver and guide will meet you at the designated meeting point, where you''ll board a comfortable vehicle for the start of your adventure."}, {"time": "09:00", "title": "Explore Da Nang''s Iconic Landmarks", "description": "Begin your journey through Da Nang''s most notable attractions, including the city''s iconic landmarks, historic sites, and cultural institutions. Your guide will provide insightful commentary and anecdotes, shedding light on the city''s rich history and cultural heritage."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy a delicious meal at a local restaurant, where you can sample the city''s culinary delights. Alternatively, you may choose to explore the surrounding area, taking in the sights and sounds of the bustling city."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Da Nang, immersing yourself in the city''s vibrant culture and stunning landscapes. Take part in additional activities, such as visiting local markets, trying your hand at traditional crafts, or simply taking in the breathtaking views of the surrounding countryside."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Your guide will escort you back to the designated meeting point, where you''ll bid farewell to Da Nang and reflect on the unforgettable experiences you''ve had during your shore excursion."}]'::jsonb, '["Air-conditioned vehicle transportation", "Expert guide services", "Lunch at a local restaurant", "Bottled water and refreshments", "Entrance fees to attractions"]'::jsonb, '["Personal expenses", "Gratuities and tips", "Travel insurance"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Tien Sa Port, near the cruise ship terminal. Please look for your driver and guide holding a sign with your name.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(128, 'Hue Shore Excursions from Chan May Port', 'vmtravel-hue-shore-excursions-from-chan-may-port-book-1-day-tour', 1, 'Embark on a captivating journey through Hue''s imperial past and vibrant present. Our expert guides will lead you through the city''s most iconic landmarks, immersing you in the region''s rich history, stunning natural beauty, and warm hospitality. From the majestic Tombs of the Emperors to the serene Thien Mu Pagoda, every moment of this shore excursion is a testament to Hue''s enduring charm.', 'Explore Hue''s rich history and culture on this 1-day shore excursion.', '[{"time": "07:30", "title": "Meet and Greet", "description": "Our friendly driver and guide will meet you at the designated meeting point, where you''ll board our comfortable vehicle and begin your journey through Hue''s breathtaking landscapes."}, {"time": "09:00", "title": "Visit the Imperial City", "description": "Step into the majestic Imperial City, the former residence of Vietnam''s emperors, and explore its grandeur, including the Forbidden Purple City, the Imperial Palace, and the Thai Hoa Palace."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and enjoy a delicious lunch at a local restaurant, savoring the flavors of Hue''s cuisine. You may also choose to explore the city''s vibrant markets or take a leisurely stroll along the Perfume River."}, {"time": "15:00", "title": "Additional Experiences", "description": "Continue your exploration of Hue''s hidden gems, including the Tombs of the Emperors, the Thien Mu Pagoda, and the bustling Dong Ba Market. Your guide will share fascinating insights into the region''s history, culture, and daily life."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the day comes to a close, our driver and guide will escort you back to the meeting point, marking the end of your unforgettable Hue shore excursion."}]'::jsonb, '["Round-trip transportation from Chan May Port", "Expert guide services", "Lunch at a local restaurant", "Entrance fees to Imperial City and other attractions"]'::jsonb, '["Personal expenses and gratuities", "Additional food and drink purchases"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '1 ngày', '08:00', 'Chan May Port, near the cruise ship terminal. Please look for our staff holding a sign with your name or group number.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(129, 'Ba Na Hills and Golden Bridge Tour from Tien Sa Port', 'vmtravel-danang-shore-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port', 1, 'Embark on a captivating journey to the majestic Ba Na Hills and Golden Bridge, a marvel of engineering and natural beauty. This guided tour from Tien Sa Port offers a unique blend of adventure, culture, and breathtaking scenery. As you ascend to the top of Ba Na Hills, you''ll be treated to panoramic views of the surrounding landscape and the chance to explore the region''s rich history and culture. The highlight of the tour is the Golden Bridge, a stunning feat of architecture that seems to defy gravity. With its intricate design and breathtaking views, this iconic landmark is a must-see for any traveler. Throughout the tour, you''ll have the opportunity to indulge in local cuisine, explore the region''s unique culture, and take in the stunning natural beauty of the area.', 'Explore the breathtaking Ba Na Hills and Golden Bridge on this guided tour from Tien Sa Port.', '[{"time": "07:30", "title": "Meet and Greet", "description": "Our experienced guide and driver will meet you at the designated meeting point, where you''ll board our comfortable vehicle and begin your journey to Ba Na Hills."}, {"time": "09:00", "title": "Main Attraction", "description": "We''ll arrive at the main attraction, where you''ll have the opportunity to explore the region''s rich history and culture, take in the breathtaking views, and enjoy the stunning scenery."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "You''ll have the chance to enjoy a delicious meal at a local restaurant or explore the region''s unique culture and cuisine at your leisure."}, {"time": "15:00", "title": "Additional Experiences", "description": "We''ll continue to explore the region, taking in the stunning scenery, learning about the local culture, and capturing unforgettable memories."}, {"time": "17:30", "title": "Tour Conclusion", "description": "We''ll return you to the designated meeting point, marking the end of our captivating journey to Ba Na Hills and the Golden Bridge."}]'::jsonb, '["Round-trip transportation from Tien Sa Port", "Experienced guide and driver", "Delicious meal at a local restaurant", "Entrance fees to main attractions", "Complimentary water and snacks"]'::jsonb, '["Personal expenses and gratuities", "Additional food and drink", "Souvenirs and shopping"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Meet your guide and driver at the Tien Sa Port cruise terminal, near the main entrance.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(130, 'Da Nang City Tour from Tien Sa Port: Explore and Shopping', 'vmtravel-danang-shore-da-nang-city-tour-from-tien-sa-port-explore-and-shopping', 2, 'Embark on a captivating journey through Da Nang''s stunning landscapes, rich history, and bustling markets. This 10-hour tour from Tien Sa Port takes you to the city''s most iconic attractions, including the Marble Mountains, Linh Ung Pagoda, and the vibrant Con Market. Enjoy a delicious lunch and explore the local cuisine, and indulge in some retail therapy at the city''s premier shopping destinations. With a knowledgeable guide and comfortable transportation, this tour is the perfect way to experience the best of Da Nang.', 'Discover Da Nang''s vibrant culture and shopping scene', '[{"time": "07:30", "title": "Meet and Greet", "description": "Our friendly guide and driver will meet you at the designated pick-up point, Tien Sa Port, and escort you to the tour vehicle for a comfortable and scenic ride to Da Nang."}, {"time": "09:00", "title": "Explore Da Nang''s Iconic Landmarks", "description": "Begin your Da Nang adventure with a visit to the Marble Mountains, a group of five marble and limestone hills featuring stunning caves, tunnels, and stunning views. Next, head to Linh Ung Pagoda, a beautiful Buddhist temple perched on a hill overlooking the city."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break for lunch at a local restaurant, where you can sample the city''s delicious cuisine and enjoy some well-deserved rest. Alternatively, you can opt for a self-guided exploration of the local market and try some street food."}, {"time": "15:00", "title": "Shopping and Cultural Experiences", "description": "Spend the afternoon exploring Da Nang''s premier shopping destinations, including the Con Market and other local boutiques. Learn about the city''s rich history and culture through interactive exhibits and engaging storytelling."}, {"time": "17:30", "title": "Tour Conclusion", "description": "After a fun-filled day of exploration and shopping, our guide and driver will escort you back to Tien Sa Port, marking the end of your Da Nang City Tour from Tien Sa Port: Explore and Shopping."}]'::jsonb, '["English-speaking guide", "Comfortable air-conditioned transportation", "Lunch at a local restaurant", "Entrance fees to attractions", "Shopping and cultural experiences"]'::jsonb, '["Personal expenses", "Gratuities and tips", "Travel insurance"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Tien Sa Port, Da Nang', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(131, 'Hoi An Day Tour from Tien Sa Port', 'vmtravel-danang-shore-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions', 2, 'Embark on a captivating journey through Hoi An''s rich history and culture on this day tour from Tien Sa Port. Our expert guides will lead you through the town''s most iconic landmarks, including the Japanese Bridge, Phuc Kien Assembly Hall, and the iconic Hoi An Ancient Town. Enjoy a delicious lunch at a local restaurant and take part in a range of activities, from traditional crafts to stunning photography opportunities. This tour is the perfect way to experience the essence of Hoi An and create unforgettable memories.', 'Explore Hoi An''s ancient charm on this day tour from Tien Sa Port.', '[{"time": "07:30", "title": "Meet and Greet", "description": "Our friendly guides will meet you at the designated meeting point, where you''ll board our comfortable vehicle and begin your journey to Hoi An."}, {"time": "09:00", "title": "Explore Hoi An Ancient Town", "description": "Discover the town''s most iconic landmarks, including the Japanese Bridge, Phuc Kien Assembly Hall, and the iconic Hoi An Ancient Town. Learn about the town''s rich history and culture from our expert guides and take in the stunning architecture and scenery."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Enjoy a delicious lunch at a local restaurant, where you can sample the region''s unique cuisine and take a break from the excitement of the day. Alternatively, you can choose to explore the town at your leisure and experience the local culture firsthand."}, {"time": "15:00", "title": "Additional Experiences", "description": "Take part in a range of activities, from traditional crafts to stunning photography opportunities. Learn about the local artisans and their techniques, and take home a unique souvenir to remember your trip."}, {"time": "17:30", "title": "Tour Conclusion", "description": "Our guides will return you to the designated meeting point, where you''ll bid farewell to Hoi An and reflect on the unforgettable experiences you''ve had during your day tour."}]'::jsonb, '["Round-trip transportation from Tien Sa Port", "Expert guides with in-depth knowledge of Hoi An''s history and culture", "Delicious lunch at a local restaurant", "Range of activities, including traditional crafts and photography opportunities"]'::jsonb, '["Personal expenses and gratuities", "Additional activities or services not specified in the itinerary"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Meet your guide at the Tien Sa Port cruise terminal, near the main entrance.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(132, 'My Son Sanctuary Tour from Tien Sa Port', 'vmtravel-danang-shore-my-son-sanctuary-tour-from-tien-sa-port-explore-now', 2, 'Embark on a captivating journey to the ancient My Son Sanctuary, a UNESCO World Heritage Site, with our expertly guided tour from Tien Sa Port. This 10-hour excursion promises an immersive experience, delving into the rich history and cultural significance of this sacred site. As we navigate through the lush Vietnamese countryside, you''ll be treated to breathtaking views and insights into the region''s storied past.', 'Explore the ancient My Son Sanctuary with a guided tour from Tien Sa Port.', '[{"time": "07:30", "title": "Tour Commencement", "description": "Our experienced guide and comfortable vehicle will meet you at the pre-arranged pickup point, marking the beginning of your My Son Sanctuary adventure."}, {"time": "09:00", "title": "Exploring the Main Attraction", "description": "As we delve into the heart of the My Son Sanctuary, you''ll be struck by the intricate carvings, majestic temples, and serene atmosphere that have captivated visitors for centuries. Our knowledgeable guide will regale you with stories of the site''s history, mythology, and cultural significance, ensuring a truly enriching experience."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Take a break and indulge in a delicious meal, either as part of our package or at a local eatery of your choice. This is an excellent opportunity to recharge and soak up the tranquil ambiance of the surrounding countryside."}, {"time": "15:00", "title": "Optional Activities", "description": "Continue to explore the sanctuary, capturing stunning photographs, and learning about the local culture through our expert guide''s engaging narrative. This is also a chance to engage with the local community, fostering a deeper understanding of the region''s customs and traditions."}, {"time": "17:30", "title": "Tour Conclusion", "description": "As the sun begins to set, our guide will escort you back to the original pickup point, marking the end of your unforgettable My Son Sanctuary tour from Tien Sa Port."}]'::jsonb, '["Expert English-speaking guide", "Comfortable, air-conditioned vehicle", "Delicious lunch at a local eatery", "Bottled water and refreshments", "Entrance fees to the My Son Sanctuary"]'::jsonb, '["Travel insurance", "Personal expenses", "Tips and gratuities"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Please assemble at the Tien Sa Port, near the cruise ship terminal, 15 minutes prior to the scheduled tour commencement time.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(133, 'Ba Na Hills Day Trip from Chan May Port: Best Shore Excursion', 'vmtravel-hue-shore-bana-hills-day-trip-from-chan-may-port-best-shore-excursion', 1, 'Embark on a memorable adventure to Ba Na Hills, one of Vietnam''s most stunning natural attractions. This day trip from Chan May Port offers a unique blend of culture, history, and breathtaking scenery. Our expert guides will take you on a journey through the rolling hills, lush forests, and picturesque villages of central Vietnam. With a mix of guided tours and free time to explore, this shore excursion is the perfect way to experience the best of Ba Na Hills.', 'Experience the breathtaking beauty of Ba Na Hills on this day trip from Chan May Port.', '[{"time": "07:30", "title": "Meet and Greet", "description": "Our friendly driver and guide will meet you at the designated meeting point, where you''ll board our comfortable vehicle for the day."}, {"time": "09:00", "title": "Main Attraction", "description": "Begin your Ba Na Hills adventure with a visit to the program''s main highlights, including the stunning Golden Bridge, the Debay Wine Cellar, and the Le Jardin D''Amour flower garden."}, {"time": "12:00", "title": "Lunch and Relaxation", "description": "Enjoy a delicious meal at one of our recommended restaurants, or take some time to explore the local market and try some street food."}, {"time": "15:00", "title": "Optional Activities", "description": "Continue your exploration of Ba Na Hills with optional activities such as a visit to the Ba Na Hills Cable Car, a ride on the Fantasy Park roller coaster, or a leisurely stroll through the gardens."}, {"time": "17:30", "title": "Tour Conclusion", "description": "After a fun-filled day, our driver and guide will return you to the original meeting point, marking the end of your Ba Na Hills day trip."}]'::jsonb, '["Round-trip transportation from Chan May Port", "English-speaking guide", "Entrance fees to Ba Na Hills attractions", "Lunch at a local restaurant"]'::jsonb, '["Personal expenses", "Optional activities and entrance fees", "Gratuities and tips"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Please meet your driver and guide at the Chan May Port cruise ship terminal, near the main entrance.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(134, 'Hue Imperial Tour from Chan May Port: Best Shore Excursions', 'vmtravel-hue-shore-hue-imperial-tour-from-chan-may-port-best-shore-excursions', 2, 'Embark on a captivating journey through Hue''s imperial past, exploring the city''s majestic landmarks and UNESCO World Heritage Sites. This comprehensive shore excursion is carefully crafted to provide an unforgettable experience, showcasing the rich history and cultural heritage of Vietnam''s former capital. From the stunning Khai Dinh Royal Tomb to the ancient Imperial Citadel, you''ll delve into the city''s fascinating past, immersing yourself in the unique blend of Western and Eastern architectural styles. Enjoy a delicious lunch at a local garden restaurant and visit the serene Thien Mu Pagoda, the oldest and most beautiful pagoda in Hue. With a seamless port pickup and a safe return to your cruise ship, this tour is designed to provide a stress-free and enriching experience.', 'Discover Hue''s majestic past and UNESCO World Heritage Sites on this immersive shore excursion.', '[{"time": "08:00 – 09:00 AM", "title": "Seamless Port Pickup", "description": "Meet your guide at Chân Mây Port between 8:00 AM and 9:00 AM. Choose from two convenient pickup options: inside the port or just outside the port gate."}, {"time": "09:00 – 10:00 AM", "title": "Arrival & Imperial Discovery", "description": "Take a scenic one-hour drive to the heart of Hue and begin your exploration of the city''s majestic past, immersing yourself in the city''s rich history and cultural heritage."}, {"time": "10:00 AM – 11:30 AM", "title": "Khai Dinh Royal Tomb", "description": "Visit the visually stunning Khai Dinh Royal Tomb, famous for its unique blend of Western and Eastern architectural styles. Marvel at the intricate designs and ornate details that make this royal resting place a must-see attraction."}, {"time": "11:30 AM – 1:00 PM", "title": "The Imperial Citadel", "description": "Step inside the ancient Imperial Citadel, a UNESCO World Heritage Site built by Emperor Gia Long in 1805. Explore the numerous ramparts, palaces, and royal structures that remain nearly original, providing a glimpse into the city''s fascinating past."}, {"time": "1:00 – 2:30 PM", "title": "Lunch & Relaxation", "description": "Enjoy a delicious lunch at a famous local garden restaurant, providing a refreshing culinary experience and a short, peaceful rest before continuing your journey."}, {"time": "2:30 – 4:00 PM", "title": "Thien Mu Pagoda – The Spiritual Icon", "description": "Visit the oldest and most beautiful pagoda in Hue, located just 3km from the Citadel on the northern bank of the Perfume River. Admire the tranquil atmosphere surrounded by ornamental plants and learn about the pagoda''s rich history and cultural significance."}, {"time": "4:00 PM", "title": "Safe Return to Port", "description": "Commence the drive back to Chân Mây Port, ensuring a safe and stress-free return to your cruise ship, typically around 4:00 PM."}, {"time": "4:00 PM", "title": "Tour Conclusion", "description": "The full-day historical experience concludes back at your Cruise ship, providing a memorable and enriching experience."}]'::jsonb, '["English-speaking guide", "Round-trip transportation from Chân Mây Port", "Lunch at a local garden restaurant", "Entrance fees to Khai Dinh Royal Tomb and Imperial Citadel", "Visit to Thien Mu Pagoda"]'::jsonb, '["Personal expenses", "Gratuities for guide and driver"]'::jsonb, '750000.00', '550000.00', '0.00', 0, '3 ngày', '08:00', 'Meet your guide at Chân Mây Port between 8:00 AM and 9:00 AM. Choose from two convenient pickup options: inside the port or just outside the port gate.', 30, 1, NULL, NULL, 'https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg', '["https://vmtravel.com/wp-content/uploads/2023/06/700x900.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hanoi-Car-Rental.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Location-Da-Nang.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Hoi-An-Location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/location-Hue.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/HCM-location.jpg", "https://vmtravel.com/wp-content/uploads/2025/10/Phu-Quoc.jpg", "https://vmtravel.com/wp-content/uploads/2023/07/ninh-bing-vietnam.jpg"]'::jsonb, NULL, 'inactive', 'open', false, false, 0, 0, 0, '0.00', NULL, '2026-06-13 10:19:59', '2026-06-15 00:49:30'),
(135, 'Tour Bà Nà Hills trong ngày từ Đà Nẵng', 'vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip', 1, 'Tour Bà Nà Hills trong ngày đưa du khách hành trình từ Đà Nẵng đến khu du lịch Sun World Ba Na Hills nổi tiếng. Trải nghiệm cáp treo ngắm nhìn toàn cảnh núi rừng, đi dạo trên Cầu Vàng được nâng đỡ bởi đôi bàn tay khổng lồ đầy nghệ thuật, khám phá kiến trúc châu Âu lãng mạn tại Làng Pháp cổ kính và tham gia hơn 105 trò chơi thú vị tại Fantasy Park. Chương trình còn kết hợp tham quan Chợ Hàn nhộn nhịp và Bán đảo Sơn Trà xanh mát.', 'Hành trình khám phá đường lên tiên cảnh Bà Nà Hills từ Đà Nẵng với Cầu Vàng, Làng Pháp và nhiều trò chơi hấp dẫn.', '[{"time": "08:00", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn trung tâm Đà Nẵng", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn trung tâm Đà Nẵng, bắt đầu hành trình khám phá Bà Nà Hills. Đây là bước khởi đầu quan trọng để đảm bảo Quý khách có một trải nghiệm tuyệt vời."}, {"time": "09:00", "title": "Trải nghiệm tuyến cáp treo đạt nhiều kỷ lục thế giới", "description": "Đến ga cáp treo, Quý khách sẽ trải nghiệm tuyến cáp treo đạt nhiều kỷ lục thế giới, thưởng ngoạn phong cảnh thiên nhiên hùng vĩ. Đây là một trong những điểm nhấn nổi bật của tour Bà Nà Hills."}, {"time": "09:30", "title": "Tham quan Cầu Vàng - biểu tượng du lịch độc đáo", "description": "Tham quan Cầu Vàng, biểu tượng du lịch độc đáo của Bà Nà Hills. Cầu Vàng được nâng đỡ bởi đôi bàn tay khổng lồ đầy nghệ thuật, tạo nên một bức tranh tuyệt đẹp."}, {"time": "09:45", "title": "Viếng chùa Linh Ứng Bà Nà thanh tịnh", "description": "Viếng chùa Linh Ứng Bà Nà, một địa điểm tâm linh thanh tịnh và yên bình. Đây là cơ hội để Quý khách thư giãn và kết nối với bản thân."}, {"time": "12:00", "title": "Khám phá Làng Pháp cổ kính", "description": "Khám phá Làng Pháp cổ kính, với kiến trúc châu Âu lãng mạn và đầy màu sắc. Đây là một trong những điểm nhấn nổi bật của tour Bà Nà Hills."}, {"time": "13:00", "title": "Vui chơi thả ga tại Fantasy Park", "description": "Vui chơi thả ga tại Fantasy Park, với hơn 105 trò chơi thú vị. Đây là cơ hội để Quý khách thư giãn và tận hưởng thời gian."}, {"time": "15:30", "title": "Xuống cáp treo và tham quan mua sắm tại Chợ Hàn", "description": "Xuống cáp treo và tham quan mua sắm tại Chợ Hàn, nơi Quý khách có thể tìm thấy các sản phẩm đặc trưng của Đà Nẵng."}, {"time": "16:30", "title": "Ngắm cảnh Bán đảo Sơn Trà", "description": "Ngắm cảnh Bán đảo Sơn Trà, một trong những điểm nhấn nổi bật của Đà Nẵng. Đây là cơ hội để Quý khách thư giãn và tận hưởng thời gian."}]'::jsonb, '["Xe và hướng dẫn viên", "Trải nghiệm tuyến cáp treo", "Tham quan Cầu Vàng", "Viếng chùa Linh Ứng Bà Nà", "Khám phá Làng Pháp", "Vui chơi thả ga tại Fantasy Park", "Tham quan mua sắm tại Chợ Hàn", "Ngắm cảnh Bán đảo Sơn Trà"]'::jsonb, '["Ăn uống", "Phí cáp treo", "Phí tham quan các điểm du lịch"]'::jsonb, '3150000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Khách sạn trung tâm Đà Nẵng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804759/danangtrip/tours/vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip/tour-006__vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip__p01__vmtravel-explore-golden-bridge.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804759/danangtrip/tours/vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip/tour-006__vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip__p01__vmtravel-explore-golden-bridge.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804756/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p03__vmtravel-french-village.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804753/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p02__vmtravel-bana-hills-danang.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 0, 4, '4.50', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(136, 'Tour Bà Nà Hills 1 ngày từ Hội An', 'vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour', 1, 'Dành cho du khách đang lưu trú tại phố cổ Hội An muốn có chuyến đi thuận tiện đến Bà Nà Hills. Xe du lịch đưa đón tận nơi, hướng dẫn viên chuyên nghiệp suốt tuyến, vé cáp treo Sun World khứ hồi, ăn buffet trưa đặc sắc tại đỉnh núi và tự do khám phá các điểm nổi tiếng như Cầu Vàng, Làng Pháp, Fantasy Park.', 'Khám phá Bà Nà Hills trọn ngày khởi hành từ phố cổ Hội An', '[{"time": "08:00", "title": "Đón xe và khởi hành từ Hội An", "description": "Xe du lịch sẽ đón Quý khách tại khách sạn khu vực Hội An và bắt đầu hành trình đến Bà Nà Hills. Hướng dẫn viên chuyên nghiệp sẽ giới thiệu về lịch trình và cung cấp thông tin cần thiết để Quý khách có thể tận hưởng chuyến đi một cách tốt nhất."}, {"time": "09:15", "title": "Lên cáp treo và trải nghiệm cảm giác lơ lửng", "description": "Sau khi đến nơi, Quý khách sẽ làm thủ tục lên cáp treo và trải nghiệm cảm giác lơ lửng giữa mây ngàn và núi non trùng điệp. Đây là một trong những điểm nhấn của chuyến đi và sẽ mang lại cho Quý khách những khoảnh khắc đáng nhớ."}, {"time": "10:00", "title": "Check-in Cầu Vàng và tham quan chùa Linh Ứng Bà Nà", "description": "Quý khách sẽ được check-in Cầu Vàng nổi tiếng thế giới và tham quan chùa Linh Ứng Bà Nà, một trong những ngôi chùa đẹp và linh thiêng nhất tại Việt Nam. Ngoài ra, Quý khách cũng sẽ được tham quan vườn hoa tình yêu Le Jardin D’Amour, một nơi lý tưởng để chụp ảnh và tận hưởng không khí lãng mạn."}, {"time": "12:00", "title": "Thưởng thức bữa trưa buffet phong phú", "description": "Quý khách sẽ được thưởng thức bữa trưa buffet phong phú tại nhà hàng Làng Pháp với hàng trăm món ngon Âu - Á. Đây là một trong những điểm nhấn của chuyến đi và sẽ mang lại cho Quý khách những trải nghiệm ẩm thực tuyệt vời."}, {"time": "13:00", "title": "Chinh phục đỉnh núi Chúa và viếng đền thờ Lĩnh Chúa Linh Từ", "description": "Quý khách sẽ được chinh phục đỉnh núi Chúa, một trong những điểm cao nhất tại Việt Nam, và viếng đền thờ Lĩnh Chúa Linh Từ, một nơi linh thiêng và thanh tịnh. Đây là một trong những điểm nhấn của chuyến đi và sẽ mang lại cho Quý khách những khoảnh khắc đáng nhớ."}, {"time": "14:30", "title": "Vui chơi tại Fantasy Park", "description": "Quý khách sẽ được vui chơi tại Fantasy Park, một trong những công viên giải trí trong nhà lớn nhất Việt Nam. Đây là một nơi lý tưởng để Quý khách có thể thư giãn và tận hưởng không khí vui vẻ."}, {"time": "16:00", "title": "Khám phá Làng Pháp cổ kính", "description": "Quý khách sẽ được khám phá Làng Pháp cổ kính, một thị trấn châu Âu thời trung cổ thu nhỏ đầy quyến rũ. Đây là một trong những điểm nhấn của chuyến đi và sẽ mang lại cho Quý khách những trải nghiệm thú vị."}, {"time": "17:00", "title": "Tập trung đi cáp treo xuống núi", "description": "Quý khách sẽ được tập trung đi cáp treo xuống núi và trở lại khách sạn tại Hội An. Đây là một trong những điểm nhấn của chuyến đi và sẽ mang lại cho Quý khách những khoảnh khắc đáng nhớ."}]'::jsonb, '["Xe du lịch đưa đón tận nơi", "Hướng dẫn viên chuyên nghiệp suốt tuyến", "Vé cáp treo Sun World khứ hồi", "Ăn buffet trưa đặc sắc tại đỉnh núi", "Tự do khám phá các điểm nổi tiếng như Cầu Vàng, Làng Pháp, Fantasy Park"]'::jsonb, '["Đồ uống và thức ăn ngoài giờ buffet", "Dịch vụ cá nhân hóa"]'::jsonb, '1625000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Đón xe tại khách sạn khu vực Hội An', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804753/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p02__vmtravel-bana-hills-danang.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804756/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p03__vmtravel-french-village.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 0, 4, '4.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(137, 'Tour Bà Nà Hills 1 ngày từ Đà Nẵng', 'vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour', 1, 'Hành trình trọn vẹn khám phá Sun World Ba Na Hills - khu du lịch hàng đầu Việt Nam. Đi cáp treo đạt nhiều kỷ lục thế giới, dạo bước trên Cầu Vàng biểu tượng, đắm chìm trong vẻ đẹp của 9 khu vườn hoa lãng mạn, vui chơi tại Fantasy Park và thưởng thức ẩm thực buffet đa dạng.', 'Hành trình ghép nhóm chất lượng cao đi Bà Nà Hills từ Đà Nẵng', '[{"time": "08:00", "title": "Đón khách tại khách sạn trung tâm Đà Nẵng", "description": "Đón Quý khách tại khách sạn trung tâm Đà Nẵng, khởi hành đi Bà Nà Hills. Xe đưa Quý khách đến ga cáp treo, bắt đầu hành trình khám phá Sun World Ba Na Hills."}, {"time": "09:00", "title": "Lên cabin cáp treo ngắm toàn cảnh đồi núi hùng vĩ", "description": "Đến ga cáp treo, lên cabin khởi hành chặng cáp treo ngắm toàn cảnh đồi núi hùng vĩ mây phủ. Hành trình này sẽ mang lại cho Quý khách những trải nghiệm tuyệt vời và ấn tượng về vẻ đẹp của thiên nhiên."}, {"time": "10:00", "title": "Tham quan Cầu Vàng và vườn hoa Le Jardin D''Amour", "description": "Tham quan Cầu Vàng - cây cầu đi bộ nổi tiếng với đôi bàn tay đá khổng lồ, dạo chơi vườn hoa Le Jardin D''Amour. Đây là những điểm đến không thể bỏ qua khi đến với Sun World Ba Na Hills."}, {"time": "12:00", "title": "Thưởng thức bữa trưa buffet quốc tế", "description": "Thưởng thức bữa trưa buffet quốc tế thịnh soạn tại nhà hàng sang trọng ở Làng Pháp. Quý khách sẽ được thưởng thức những món ăn đa dạng và phong phú từ các nền ẩm thực khác nhau."}, {"time": "13:00", "title": "Viếng đền Lĩnh Chúa Linh Từ", "description": "Viếng đền Lĩnh Chúa Linh Từ tại đỉnh núi Chúa cao 1.487m để cầu bình an và ngắm nhìn toàn cảnh thành phố. Đây là một trong những điểm đến linh thiêng và đẹp nhất tại Sun World Ba Na Hills."}, {"time": "14:00", "title": "Khám phá Fantasy Park", "description": "Khám phá khu vui chơi trong nhà Fantasy Park với hơn 105 trò chơi phiêu lưu, cảm giác mạnh hấp dẫn. Quý khách sẽ được trải nghiệm những cảm giác mới mẻ và thú vị tại đây."}, {"time": "15:00", "title": "Tự do check-in Làng Pháp", "description": "Tự do check-in các góc phố cổ kính mang phong cách châu Âu tại Làng Pháp. Quý khách sẽ được khám phá và chụp ảnh tại những điểm đến đẹp nhất tại đây."}, {"time": "15:30", "title": "Đi cáp treo xuống núi", "description": "Đi cáp treo xuống núi, xe đưa Quý khách về lại khách sạn tại Đà Nẵng. Kết thúc hành trình khám phá Sun World Ba Na Hills, Quý khách sẽ mang lại những kỷ niệm đẹp và ấn tượng về vẻ đẹp của thiên nhiên."}]'::jsonb, '["Vé cáp treo khứ hồi", "Bữa trưa buffet quốc tế", "Hướng dẫn viên"]'::jsonb, '["Đồ uống", "Tiền tip cho hướng dẫn viên"]'::jsonb, '1625000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Đón khách tại khách sạn trung tâm Đà Nẵng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804744/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p01__vmtravel-bana-hills-big-group-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804744/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p01__vmtravel-bana-hills-big-group-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804747/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p02__vmtravel-bana-hills-in-december.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 0, 3, '3.33', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(138, 'Tour Bà Nà Hills Đêm và Ngắm Hoàng Hôn Cầu Vàng', 'vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour', 1, 'Trải nghiệm Bà Nà Hills về đêm cực kỳ lãng mạn và mát mẻ. Tour bắt đầu từ chiều giúp du khách đón hoàng hôn rực rỡ trên Cầu Vàng lúc thưa người, dạo quanh Làng Pháp cổ kính trong ánh đèn vàng huyền ảo, xem biểu diễn nghệ thuật ánh sáng nghệ thuật và thưởng thức buffet đặc sắc kèm bia tươi tại Beer Plaza nhộn nhịp.', 'Ngắm hoàng hôn lãng mạn trên Cầu Vàng và trải nghiệm thế giới đêm huyền ảo tại Làng Pháp Bà Nà Hills.', '[{"time": "14:00", "title": "Đón Quý Khách tại Khách Sạn", "description": "Chúng tôi sẽ đón Quý khách tại khách sạn và bắt đầu hành trình khám phá Bà Nà Hills về đêm. Chúng tôi sẽ đảm bảo rằng Quý khách có một chuyến đi an toàn và thoải mái."}, {"time": "15:00", "title": "Lên Cáp Treo và Ngắm Nhìn Cánh Rừng Nguyên Sinh", "description": "Chúng tôi sẽ lên cáp treo và ngắm nhìn cánh rừng nguyên sinh xanh mướt trải dài dưới chân núi. Quý khách sẽ có cơ hội để chụp ảnh và tận hưởng không khí mát mẻ của Bà Nà Hills."}, {"time": "15:30", "title": "Dạo Bước trên Cầu Vàng và Tham Quan Vườn Hoa Le Jardin D''Amour", "description": "Chúng tôi sẽ dạo bước trên Cầu Vàng lúc thưa khách, tham quan vườn hoa Le Jardin D''Amour và viếng chùa Linh Ứng. Quý khách sẽ có cơ hội để khám phá và chụp ảnh tại những địa điểm này."}, {"time": "16:30", "title": "Chiêm Ngưỡng Hoàng Hôn Lãng Mạn trên Đỉnh Núi", "description": "Chúng tôi sẽ chiêm ngưỡng hoàng hôn lãng mạn trên đỉnh núi và ngắm nhìn Làng Pháp bắt đầu lên đèn lung linh. Quý khách sẽ có cơ hội để chụp ảnh và tận hưởng không khí lãng mạn của Bà Nà Hills."}, {"time": "18:30", "title": "Trải Nghiệm Chương Trình Nghệ Thuật Ánh Sáng ''After Glow Show''", "description": "Chúng tôi sẽ trải nghiệm chương trình nghệ thuật ánh sáng ''After Glow Show'' đầy màu sắc và huyền ảo. Quý khách sẽ có cơ hội để xem biểu diễn nghệ thuật và tận hưởng không khí sôi động của Bà Nà Hills."}, {"time": "19:00", "title": "Thưởng Thức Buffet Tối Quốc Tế tại Beer Plaza", "description": "Chúng tôi sẽ thưởng thức buffet tối quốc tế hoành tráng tại Beer Plaza cùng không khí lễ hội sôi động. Quý khách sẽ có cơ hội để thưởng thức ẩm thực và tận hưởng không khí nhộn nhịp của Bà Nà Hills."}, {"time": "19:30", "title": "Tự Do Đi Dạo Ngắm Cảnh Bà Nà về Đêm", "description": "Chúng tôi sẽ tự do đi dạo ngắm cảnh Bà Nà về đêm, tận hưởng bầu không khí se lạnh. Quý khách sẽ có cơ hội để khám phá và chụp ảnh tại những địa điểm này."}, {"time": "21:00", "title": "Lên Cáp Treo xuống Núi và Xe Đưa Quý Khách trở lại Khách Sạn", "description": "Chúng tôi sẽ lên cáp treo xuống núi và xe đưa Quý khách trở lại khách sạn kết thúc tour. Chúng tôi sẽ đảm bảo rằng Quý khách có một chuyến đi an toàn và thoải mái."}]'::jsonb, '["Vé cáp treo lên núi", "Thưởng thức buffet tối quốc tế tại Beer Plaza", "Trải nghiệm chương trình nghệ thuật ánh sáng ''After Glow Show''"]'::jsonb, '["Vé vào cửa các địa điểm", "Thức ăn và đồ uống ngoài buffet tối quốc tế"]'::jsonb, '1475000.00', '0.00', '0.00', 0, '8 giờ', '14:00', 'Chúng tôi sẽ đón Quý khách tại khách sạn và đưa đến điểm xuất phát của tour.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804734/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p01__vmtravel-ba-na-hills-night-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804734/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p01__vmtravel-ba-na-hills-night-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804737/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p02__vmtravel-event-at-bana-hills-by-night.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804740/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p03__vmtravel-sunset-bana-hills-da-nang.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 2, 1, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(139, 'Tour Bà Nà Hills và Cầu Vàng từ cảng Tiên Sa', 'vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port', 1, 'Hành trình được thiết kế tối ưu dành riêng cho du khách từ các du thuyền cập cảng Tiên Sa muốn tham quan điểm du lịch nổi tiếng nhất miền Trung - Bà Nà Hills. Du khách sẽ trải nghiệm cáp treo ngắm cảnh rừng núi, đi dạo trên Cầu Vàng biểu tượng, tham quan Làng Pháp lộng lẫy và dùng bữa trưa buffet quốc tế thịnh soạn trước khi trở về cảng đúng giờ tàu chạy.', 'Tour khám phá Bà Nà Hills đón từ cảng Tiên Sa dành riêng cho du khách tàu biển', '[{"time": "08:00", "title": "Xe và hướng dẫn viên đón Quý khách tại cảng Tiên Sa", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại cảng Tiên Sa, trong hoặc ngoài cổng cảng theo yêu cầu, và khởi hành đi Bà Nà Hills. Đây là bước đầu tiên của hành trình khám phá Bà Nà Hills và Cầu Vàng."}, {"time": "09:30", "title": "Lên cáp treo thưởng ngoạn phong cảnh mây ngàn và bờ biển Đà Nẵng", "description": "Sau khi đến chân núi Bà Nà, Quý khách sẽ lên cáp treo để thưởng ngoạn phong cảnh mây ngàn và bờ biển Đà Nẵng từ xa. Đây là một trong những điểm nhấn của hành trình này, mang lại cho Quý khách những khoảnh khắc tuyệt đẹp và ấn tượng."}, {"time": "10:00", "title": "Dạo bước trên Cầu Vàng - Hands of God và tham quan vườn hoa Le Jardin D''Amour", "description": "Sau khi lên cáp treo, Quý khách sẽ dạo bước trên Cầu Vàng - Hands of God, một biểu tượng nổi tiếng của Bà Nà Hills. Sau đó, Quý khách sẽ tham quan vườn hoa Le Jardin D''Amour, một nơi lãng mạn và tuyệt đẹp. Cuối cùng, Quý khách sẽ viếng chùa Linh Ứng Bà Nà, một điểm nhấn tâm linh của hành trình này."}, {"time": "12:00", "title": "Khám phá Làng Pháp cổ kính và thưởng thức bữa trưa buffet quốc tế", "description": "Sau khi tham quan các điểm nhấn trên, Quý khách sẽ khám phá Làng Pháp cổ kính, với các lâu đài mang phong cách Gothic. Sau đó, Quý khách sẽ thưởng thức bữa trưa buffet quốc tế thịnh soạn tại nhà hàng, một trong những điểm nhấn ẩm thực của hành trình này."}, {"time": "15:30", "title": "Xuống cáp treo và trở lại cảng Tiên Sa", "description": "Sau khi dùng bữa trưa, Quý khách sẽ xuống cáp treo và trở lại cảng Tiên Sa. Xe sẽ đưa Quý khách trở lại cảng trước giờ tàu rời bến tối thiểu 1.5 giờ, đảm bảo Quý khách có thể trở lại tàu đúng giờ."}]'::jsonb, '["Xe và hướng dẫn viên", "Cáp treo", "Bữa trưa buffet quốc tế", "Điểm thăm quan Làng Pháp và Cầu Vàng"]'::jsonb, '["Thức ăn và nước uống ngoài giờ trưa", "Các chi phí cá nhân khác"]'::jsonb, '2300000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Xe và hướng dẫn viên sẽ đón Quý khách tại cảng Tiên Sa, trong hoặc ngoài cổng cảng theo yêu cầu.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804725/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p01__vmtravel-bana-hills-cable-car-in-da-nang.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804725/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p01__vmtravel-bana-hills-cable-car-in-da-nang.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804728/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p02__vmtravel-bana-hills.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804731/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p03__vmtravel-bana-hills-tour-from-chan-may-port.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 0, 4, '3.75', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(140, 'Tour Bà Nà Hills Buổi Chiều, Cầu Vàng và Cầu Rồng Về Đêm', 'recrawl-018-venusvietnamtravel-afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour-venustravel', 1, 'Khởi hành từ Đà Nẵng, chúng ta sẽ đến Bà Nà Hills vào buổi chiều mát mẻ. Sau khi tham quan các điểm du lịch tại Bà Nà, chúng ta sẽ lên Cầu Vàng để ngắm hoàng hôn rực rỡ. Sau đó, chúng ta sẽ về đến Đà Nẵng và đến Cầu Rồng để ngắm Cầu Rồng phun lửa/nước về đêm. Đây sẽ là một hành trình tuyệt vời để bạn trải nghiệm vẻ đẹp của Đà Nẵng về đêm.', 'Khám phá Bà Nà Hills buổi chiều mát mẻ, ngắm hoàng hôn rực rỡ trên Cầu Vàng và ngắm Cầu Rồng phun lửa/nước về đêm tại Đà Nẵng.', '[{"time":"14:00","title":"Khởi hành từ Đà Nẵng","description":"Chúng ta sẽ khởi hành từ Đà Nẵng vào buổi chiều để đến Bà Nà Hills."},{"time":"15:00","title":"Tham quan Bà Nà Hills","description":"Chúng ta sẽ tham quan các điểm du lịch tại Bà Nà Hills, bao gồm các công viên, khu vui chơi và các điểm tham quan khác."},{"time":"17:00","title":"Lên Cầu Vàng","description":"Chúng ta sẽ lên Cầu Vàng để ngắm hoàng hôn rực rỡ."},{"time":"19:00","title":"Về đến Đà Nẵng","description":"Chúng ta sẽ về đến Đà Nẵng sau khi ngắm hoàng hôn trên Cầu Vàng."},{"time":"20:00","title":"Ngắm Cầu Rồng phun lửa\/nước","description":"Chúng ta sẽ đến Cầu Rồng để ngắm Cầu Rồng phun lửa\/nước về đêm."}]'::jsonb, '["Vé tham quan Bà Nà Hills","Vé lên Cầu Vàng","Vé ngắm Cầu Rồng phun lửa\/nước","Hướng dẫn viên","Xe đưa đón"]'::jsonb, '["Ăn uống","Đồ uống","Phí tham quan các điểm du lịch khác"]'::jsonb, '1540750.00', '0.00', '0.00', 0, '7.5 giờ', '11:30', 'Chúng ta sẽ gặp nhau tại Bến xe Đà Nẵng vào lúc 13:30 để khởi hành.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804996/danangtrip/tours/bana-hills-afternoon-night/tour-001__p01__venus-video-scaled.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804996/danangtrip/tours/bana-hills-afternoon-night/tour-001__p01__venus-video-scaled.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804999/danangtrip/tours/bana-hills-afternoon-night/tour-001__p02__pexels-28297412.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780805002/danangtrip/tours/bana-hills-afternoon-night/tour-001__p03__pexels-20602155.jpg"]'::jsonb, NULL, 'active', 'open', true, true, 3, 0, 2, '4.50', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(141, 'Tour chùa Linh Ứng và Ngũ Hành Sơn từ Hội An', 'vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an', 2, 'Tour khám phá nửa ngày khởi hành từ Hội An đưa du khách chiêm ngưỡng vẻ đẹp thiên nhiên và tâm linh của Đà Nẵng. Viếng chùa Linh Ứng Sơn Trà thanh tịnh hướng ra biển Đông, khám phá các ngọn núi Ngũ Hành Sơn huyền bí gắn liền với truyền thuyết dân gian, ngắm các hang động thạch nhũ lung linh và tham quan làng nghề đá điêu khắc tinh xảo.', 'Viếng Phật Bà Sơn Trà hướng biển và khám phá hang động Ngũ Hành Sơn kỳ bí, đón trả tận nơi từ Hội An.', '[{"time": "07:30 - 08:00", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn Hội An", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn Hội An, bắt đầu hành trình khám phá Đà Nẵng. Trước khi khởi hành, Quý khách sẽ được hướng dẫn viên cung cấp thông tin chi tiết về tour và giải đáp bất kỳ câu hỏi nào."}, {"time": "08:30", "title": "Viếng Chùa Linh Ứng Bán đảo Sơn Trà", "description": "Đến Chùa Linh Ứng Bán đảo Sơn Trà, Quý khách sẽ chiêm ngưỡng tượng Phật Bà Quan Âm cao 67m, ngắm biển trời xanh biếc và cảm nhận sự thanh tịnh của chùa. Đây là một trong những điểm đến nổi tiếng của Đà Nẵng và là nơi linh thiêng đối với người dân địa phương."}, {"time": "09:30", "title": "Khám phá Ngũ Hành Sơn", "description": "Đến Ngũ Hành Sơn, Quý khách sẽ leo núi và khám phá các hang động linh thiêng như động Huyền Không, động Tàng Chơn và viếng chùa cổ Linh Ứng. Các hang động này được tạo thành từ đá vôi và có kiến trúc độc đáo, tạo nên một cảnh quan kỳ bí và huyền bí."}, {"time": "11:00", "title": "Ghé thăm làng nghề điêu khắc đá mỹ nghệ Non Nước", "description": "Ghé thăm làng nghề điêu khắc đá mỹ nghệ Non Nước, Quý khách sẽ được tham quan và học hỏi về nghề truyền thống hàng trăm năm của người dân địa phương. Làng nghề này nổi tiếng với các tác phẩm điêu khắc đá tinh xảo và độc đáo."}, {"time": "12:00", "title": "Thưởng thức bữa trưa ấm cúng", "description": "Thưởng thức bữa trưa ấm cúng với ẩm thực Việt Nam thanh đạm tại nhà hàng địa phương. Bữa trưa này sẽ là cơ hội để Quý khách trải nghiệm ẩm thực địa phương và giao lưu với người dân địa phương."}, {"time": "13:00", "title": "Xe đưa đoàn khởi hành trở về Hội An", "description": "Xe sẽ đưa đoàn khởi hành trở về Hội An, trả Quý khách tại điểm đón ban đầu. Đây là kết thúc của một hành trình khám phá Đà Nẵng đầy thú vị và đáng nhớ."}]'::jsonb, '["Xe đưa đón", "Hướng dẫn viên", "Bữa trưa", "Văn phòng phẩm"]'::jsonb, '["Phí vào cửa", "Phí ăn uống ngoài giờ", "Phí lưu trú"]'::jsonb, '700000.00', '0.00', '0.00', 0, '6 giờ', '07:30', 'Khách sạn Hội An, điểm đón ban đầu', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804917/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p01__vmtravel-marble-mountain-tour-from-da-nang.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804917/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p01__vmtravel-marble-mountain-tour-from-da-nang.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804920/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p02__vmtravel-linh-ung-pagoda-danang-vietnam.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804923/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p03__vmtravel-best-time-to-visit-linh-ung-pagoda-da-nang.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 2, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(142, 'Tour Hội An trong ngày từ cảng Tiên Sa', 'vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions', 2, 'Giải pháp du lịch hoàn hảo cho khách cập cảng Tiên Sa muốn ghé thăm Phố cổ Hội An - Di sản văn hóa thế giới được UNESCO công nhận. Tour kết hợp tham quan các công trình cổ độc đáo của phố cổ, đi thuyền thúng vui nhộn tại rừng dừa Cam Thanh và thưởng thức bữa trưa đặc sản vùng miền.', 'Hành trình khám phá phố cổ Hội An và trải nghiệm chèo thuyền thúng rừng dừa nước Cam Thanh', '[{"time": "08:00", "title": "Xe đón Quý khách tại cảng Tiên Sa", "description": "Xe sẽ đón Quý khách tại cảng Tiên Sa (Đà Nẵng) với bảng tên chào mừng khởi hành đi Hội An. Đây là bước đầu tiên của hành trình khám phá phố cổ Hội An và rừng dừa nước Cam Thanh."}, {"time": "09:30", "title": "Tham quan khu phố cổ Hội An", "description": "Đến Hội An, Quý khách sẽ được dạo bộ ngắm khu phố cổ kính với Chùa Cầu, hội quán Phúc Kiến và các di tích cổ xưa trăm tuổi. Đây là cơ hội để Quý khách chụp ảnh lưu niệm và trải nghiệm văn hóa địa phương."}, {"time": "11:00", "title": "Trải nghiệm đi thuyền thúng tại rừng dừa nước Cam Thanh", "description": "Di chuyển đến rừng dừa nước Cam Thanh, Quý khách sẽ được trải nghiệm đi thuyền thúng mộc mạc khám phá kênh rạch xanh mát. Đây là một trong những hoạt động thú vị và độc đáo của tour."}, {"time": "12:30", "title": "Thưởng thức bữa trưa đặc sản vùng miền", "description": "Thưởng thức bữa trưa đậm đà phong vị ẩm thực Hội An tại nhà hàng địa phương chất lượng. Quý khách sẽ được thưởng thức các món ăn đặc sản của vùng miền này."}, {"time": "14:00", "title": "Tự do mua sắm đồ thủ công mỹ nghệ", "description": "Tự do mua sắm đồ thủ công mỹ nghệ, may mặc lấy ngay hoặc chụp ảnh lưu niệm phố cổ. Đây là cơ hội để Quý khách tìm kiếm những món quà lưu niệm đặc biệt."}, {"time": "15:30", "title": "Xe đưa Quý khách trở lại cảng Tiên Sa", "description": "Xe sẽ đưa Quý khách trở lại cảng Tiên Sa trước giờ tàu rời bến ít nhất 1.5 giờ, kết thúc chuyến tham quan."}]'::jsonb, '["Xe đưa đón, hướng dẫn viên, bữa trưa đặc sản vùng miền, đi thuyền thúng tại rừng dừa nước Cam Thanh"]'::jsonb, '["Phí ăn uống ngoài giờ, phí mua sắm"]'::jsonb, '1500000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Xe sẽ đón Quý khách tại cảng Tiên Sa (Đà Nẵng) với bảng tên chào mừng khởi hành đi Hội An.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804845/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p01__vmtravel-hoi-an-full-day-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804845/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p01__vmtravel-hoi-an-full-day-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804826/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p03__vmtravel-cam-thanh-coconut-village.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804848/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p03__vmtravel-best-time-visit-hoian-coconut.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 2, 3, '4.33', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(143, 'Tour riêng Hội An trong ngày từ Đà Nẵng', 'vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel', 2, 'Trải nghiệm sự riêng tư và cá nhân hóa tối đa với dịch vụ xe đưa đón riêng và hướng dẫn viên đồng hành riêng suốt tuyến. Hành trình đưa bạn khám phá rừng dừa Cam Thanh bằng thuyền thúng, đi bộ tham quan di sản phố cổ Hội An sâu sắc và đi thuyền thả hoa đăng yên bình trên sông Hoài.', 'Khám phá rừng dừa Cam Thanh và phố cổ Hội An bằng thuyền thúng và thả hoa đăng', '[{"time": "13:30", "title": "Xe riêng và hướng dẫn viên đón Quý khách tại khách sạn Đà Nẵng", "description": "Xe riêng và hướng dẫn viên sẽ đón Quý khách tại khách sạn Đà Nẵng và bắt đầu hành trình khám phá Hội An. Quý khách sẽ được trải nghiệm sự riêng tư và cá nhân hóa tối đa với dịch vụ xe đưa đón riêng và hướng dẫn viên đồng hành riêng suốt tuyến."}, {"time": "15:00", "title": "Khám phá rừng dừa Cam Thanh bằng thuyền thúng riêng tư", "description": "Quý khách sẽ được khám phá rừng dừa Cam Thanh bằng thuyền thúng riêng tư, xem biểu diễn múa thúng và nghe ca vọng cổ trên sông. Đây là một trải nghiệm độc đáo và thú vị mà Quý khách sẽ không thể bỏ qua."}, {"time": "16:00", "title": "Đi bộ tham quan các di sản nổi bật tại Phố cổ Hội An", "description": "Quý khách sẽ được đi bộ tham quan các di sản nổi bật tại Phố cổ Hội An, bao gồm Chùa Cầu, hội quán Quảng Đông và nhà cổ Tấn Ký. Hướng dẫn viên riêng sẽ giới thiệu về lịch sử và văn hóa của các di sản này."}, {"time": "18:00", "title": "Thưởng thức bữa tối ấm cúng tại nhà hàng ẩm thực Hội An cao cấp", "description": "Quý khách sẽ được thưởng thức bữa tối ấm cúng tại nhà hàng ẩm thực Hội An cao cấp ven sông Hoài. Bữa tối sẽ bao gồm các món ăn đặc sản của Hội An và sẽ được phục vụ bởi đội ngũ nhân viên chuyên nghiệp."}, {"time": "19:00", "title": "Ngồi thuyền gỗ thả đèn hoa đăng lãng mạn", "description": "Quý khách sẽ được ngồi thuyền gỗ thả đèn hoa đăng lãng mạn trên dòng sông Hoài thơ mộng. Đây là một trải nghiệm lãng mạn và thú vị mà Quý khách sẽ không thể bỏ qua."}, {"time": "19:30", "title": "Xe riêng đưa Quý khách thư thái trở lại Đà Nẵng", "description": "Xe riêng sẽ đưa Quý khách thư thái trở lại Đà Nẵng, trả tận sảnh khách sạn. Quý khách sẽ được trải nghiệm sự riêng tư và cá nhân hóa tối đa với dịch vụ xe đưa đón riêng và hướng dẫn viên đồng hành riêng suốt tuyến."}]'::jsonb, '["Dịch vụ xe đưa đón riêng", "Hướng dẫn viên đồng hành riêng suốt tuyến", "Bữa tối ấm cúng tại nhà hàng ẩm thực Hội An cao cấp", "Thuyền gỗ thả đèn hoa đăng"]'::jsonb, '["Bữa sáng và bữa trưa", "Rượu và các loại đồ uống khác"]'::jsonb, '2750000.00', '0.00', '0.00', 0, '1 ngày', '13:30', 'Khách sạn Đà Nẵng, 8h00 sáng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804829/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p01__vmtravel-visit-hoian.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804829/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p01__vmtravel-visit-hoian.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804832/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p03__vmtravel-coffee-hoian.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 3, '4.33', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(144, 'Tour Hội An trong ngày từ Đà Nẵng', 'vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour', 2, 'Tour chiều tối khởi hành từ Đà Nẵng đưa du khách đến với thiên nhiên trong lành tại rừng dừa Cam Thanh bằng thuyền thúng truyền thống vui nhộn. Sau đó, hòa mình vào không gian cổ kính, hoài niệm của Phố cổ Hội An lúc hoàng hôn lên đèn và thả hoa đăng cầu may mắn trên sông Hoài.', 'Khám phá rừng dừa Cam Thanh và phố cổ Hội An rực rỡ lồng đèn', '[{"time": "13:45", "title": "Đón xe và hướng dẫn viên tại khách sạn Đà Nẵng", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn Đà Nẵng và bắt đầu hành trình khám phá Hội An."}, {"time": "15:00", "title": "Trải nghiệm đi thuyền thúng rừng dừa Bảy Mẫu Cam Thanh", "description": "Đến rừng dừa Bảy Mẫu Cam Thanh, Quý khách sẽ được trải nghiệm đi thuyền thúng mộc mạc len lỏi vào rừng dừa, xem biểu diễn múa thúng giật gân và cảm nhận không khí trong lành của thiên nhiên."}, {"time": "16:00", "title": "Khám phá Phố cổ Hội An", "description": "Bắt đầu hành trình đi bộ khám phá Phố cổ Hội An: tham quan Chùa Cầu, hội quán Phúc Kiến, nhà cổ và dạo chơi phố đèn lồng. Quý khách sẽ được cảm nhận không khí cổ kính, hoài niệm của Phố cổ Hội An."}, {"time": "18:00", "title": "Dùng bữa tối đặc sản Hội An và thả hoa đăng", "description": "Dùng bữa tối đặc sản Hội An tại nhà hàng và trải nghiệm thả hoa đăng lãng mạn trên dòng sông Hoài thơ mộng. Quý khách sẽ được cảm nhận không khí lãng mạn và thư giãn."}, {"time": "19:30", "title": "Trở về Đà Nẵng", "description": "Tập trung lên xe khởi hành trở về Đà Nẵng. Trả khách tại điểm đón ban đầu."}]'::jsonb, '["Xe đưa đón, hướng dẫn viên, bữa tối đặc sản Hội An, thả hoa đăng"]'::jsonb, '["Vé vào cửa các điểm tham quan, đồ uống ngoài giờ ăn"]'::jsonb, '900000.00', '0.00', '0.00', 0, '6 giờ', '13:45', 'Điểm đón tại khách sạn Đà Nẵng, hướng dẫn viên sẽ đón Quý khách tại đây.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804823/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p02__vmtravel-hoian-in-vietnam.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804826/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p03__vmtravel-cam-thanh-coconut-village.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 2, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(145, 'Tour Đà Nẵng và Hội An trọn ngày', 'vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities', 2, 'Một tour kết hợp tuyệt vời đưa bạn đi từ những ngọn núi Ngũ Hành Sơn kỳ vĩ, chùa Linh Ứng Sơn Trà hướng biển của Đà Nẵng đến rừng dừa Bảy Mẫu xanh mát tại Cam Thanh, rồi dừng chân tại phố cổ Hội An rực rỡ lồng đèn để ngắm Chùa Cầu cổ kính và thưởng thức bữa tối ngon miệng.', 'Kết hợp khám phá danh thắng Đà Nẵng và vẻ đẹp hoài cổ phố cổ Hội An trong một ngày', '[{"time": "09:00", "title": "Đón khách tại khách sạn và khởi hành đi tham quan bán đảo Sơn Trà", "description": "Chúng tôi sẽ đón Quý khách tại khách sạn và khởi hành đi tham quan bán đảo Sơn Trà, nơi có chùa Linh Ứng Sơn Trà hướng biển. Đây là một trong những điểm đến nổi tiếng của Đà Nẵng, với cảnh quan tuyệt đẹp và lịch sử phong phú."}, {"time": "11:00", "title": "Tham quan Ngũ Hành Sơn và động Huyền Không", "description": "Sau đó, chúng tôi sẽ di chuyển đến Ngũ Hành Sơn, nơi có động Huyền Không kỳ vĩ. Bạn sẽ được leo núi và ngắm cảnh tuyệt đẹp của động Huyền Không, cũng như tham quan làng đá mỹ nghệ Non Nước để tìm hiểu về nghệ thuật tạo tác đá của người dân địa phương."}, {"time": "13:00", "title": "Thưởng thức bữa trưa đặc sản Việt Nam tại nhà hàng", "description": "Sau khi tham quan Ngũ Hành Sơn, chúng tôi sẽ đưa Quý khách đến Chợ Hàn cổ kính để tham quan và sắm sửa. Sau đó, chúng tôi sẽ thưởng thức bữa trưa đặc sản Việt Nam tại một nhà hàng địa phương, với các món ăn như bánh xèo, bánh cuốn, và nhiều món ăn khác."}, {"time": "15:00", "title": "Trải nghiệm chèo thuyền thúng ngắm cảnh rừng dừa nước Cam Thanh", "description": "Sau bữa trưa, chúng tôi sẽ khởi hành đi Hội An, nơi bạn sẽ trải nghiệm chèo thuyền thúng ngắm cảnh rừng dừa nước Cam Thanh xanh mát. Đây là một trong những điểm đến độc đáo và thú vị của Hội An, nơi bạn có thể ngắm cảnh tuyệt đẹp của rừng dừa và tìm hiểu về cuộc sống của người dân địa phương."}, {"time": "17:00", "title": "Khám phá Phố cổ Hội An", "description": "Sau khi trải nghiệm chèo thuyền thúng, chúng tôi sẽ đưa Quý khách đến Phố cổ Hội An để khám phá. Bạn sẽ đi bộ qua các ngõ nhỏ, ngắm Chùa Cầu cổ kính, hội quán Phúc Kiến, và các ngôi nhà cổ trăm tuổi. Đây là một trong những điểm đến nổi tiếng của Hội An, với cảnh quan tuyệt đẹp và lịch sử phong phú."}, {"time": "19:00", "title": "Thưởng thức bữa tối ấm cúng với đặc sản Hội An", "description": "Cuối cùng, chúng tôi sẽ đưa Quý khách đến thưởng thức bữa tối ấm cúng với đặc sản Hội An, bao gồm các món ăn như cao lầu, mì Quảng, và hoành thánh. Đây là một trong những trải nghiệm ẩm thực tuyệt vời của Hội An, với các món ăn độc đáo và ngon miệng."}, {"time": "19:30", "title": "Lên xe trở lại Đà Nẵng", "description": "Sau bữa tối, chúng tôi sẽ đưa Quý khách lên xe trở lại Đà Nẵng, kết thúc một ngày hành trình ý nghĩa và đầy thú vị."}]'::jsonb, '["Vé tham quan các điểm đến", "Bữa trưa đặc sản Việt Nam", "Bữa tối ấm cúng với đặc sản Hội An"]'::jsonb, '["Vé máy bay", "Phí lưu trú"]'::jsonb, '1300000.00', '0.00', '0.00', 0, '1 ngày', '09:00', 'Khách sạn của Quý khách', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804804/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p01__vmtravel-da-nang-and-hoi-an-city-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804804/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p01__vmtravel-da-nang-and-hoi-an-city-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804808/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p02__vmtravel-da-nang-city-tour-1.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804811/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p03__vmtravel-hoian-lantern-festival.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 3, '4.33', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(146, 'Tour Đại Nội Huế từ cảng Chân Mây', 'vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions', 3, 'Chuyến tham quan được thiết kế tối ưu hóa thời gian đón trả tại cảng Chân Mây dành riêng cho du khách tàu biển. Khám phá những di sản nổi tiếng nhất cố đô Huế bao gồm Lăng Khải Định độc đáo, hoàng thành Đại Nội cổ kính, chùa Thiên Mụ thơ mộng bên dòng sông Hương và thưởng thức bữa trưa đặc sản.', 'Hành trình khám phá di sản Huế thiết kế riêng cho du khách tàu biển đón từ cảng Chân Mây', '[{"time": "08:00", "title": "Đón Quý khách tại cảng Chân Mây", "description": "Đón Quý khách tại cảng Chân Mây (trong hoặc ngoài cổng cảng theo thỏa thuận) với bảng tên chào mừng khởi hành đi Huế. Chúng tôi sẽ đảm bảo rằng Quý khách được đón đúng giờ và có một chuyến tham quan trọn vẹn."}, {"time": "08:30", "title": "Di chuyển đến cố đô Huế", "description": "Di chuyển chặng đường ngắm nhìn cảnh đồng quê thanh bình trước khi tiến vào cố đô Huế. Quãng đường này sẽ mang lại cho Quý khách những hình ảnh đẹp về cuộc sống nông thôn Việt Nam."}, {"time": "09:30", "title": "Tham quan Lăng Khải Định", "description": "Tham quan Lăng Khải Định - công trình lăng tẩm có thiết kế trang trí độc đáo phối hợp các phong cách Đông - Tây. Lăng Khải Định là một trong những công trình kiến trúc độc đáo nhất của Việt Nam và sẽ mang lại cho Quý khách những trải nghiệm khó quên."}, {"time": "11:30", "title": "Khám phá Đại Nội Huế", "description": "Khám phá Đại Nội Huế - kinh thành lịch sử triều đại nhà Nguyễn, di sản văn hóa thế giới được UNESCO công nhận. Đại Nội Huế là một trong những di sản văn hóa quan trọng nhất của Việt Nam và sẽ mang lại cho Quý khách những hiểu biết sâu sắc về lịch sử và văn hóa của đất nước này."}, {"time": "13:00", "title": "Dùng bữa trưa đặc sản", "description": "Dùng bữa trưa đặc sản Huế ngon miệng tại nhà hàng sân vườn và nghỉ ngơi nhẹ nhàng. Bữa trưa này sẽ mang lại cho Quý khách những trải nghiệm ẩm thực phong phú và đa dạng của Huế."}, {"time": "14:30", "title": "Viếng chùa Thiên Mụ", "description": "Viếng chùa Thiên Mụ - ngôi chùa cổ kính nổi tiếng nhất Huế nằm bên dòng sông Hương thơ mộng. Chùa Thiên Mụ là một trong những di tích lịch sử quan trọng nhất của Huế và sẽ mang lại cho Quý khách những hiểu biết sâu sắc về lịch sử và văn hóa của đất nước này."}, {"time": "15:00", "title": "Trở lại cảng Chân Mây", "description": "Xe đưa Quý khách trở lại cảng Chân Mây, đảm bảo có mặt tại cảng trước giờ tàu chạy ít nhất 1.5 giờ. Chúng tôi sẽ đảm bảo rằng Quý khách được đưa trở lại cảng đúng giờ và có một chuyến tham quan trọn vẹn."}]'::jsonb, '["Bữa trưa đặc sản Huế", "Văn phòng phẩm", "Dịch vụ hướng dẫn viên"]'::jsonb, '["Phí tham quan các di tích", "Phí ăn uống ngoài giờ", "Phí vận chuyển ngoài giờ"]'::jsonb, '4600000.00', '0.00', '0.00', 0, '8 giờ', '08:00', 'Đón Quý khách tại cảng Chân Mây (trong hoặc ngoài cổng cảng theo thỏa thuận)', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804904/danangtrip/tours/vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions/tour-024__vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions__p02__vmtravel-hue-imperial.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804908/danangtrip/tours/vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions/tour-024__vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions__p03__vmtravel-car-rental-from-port.jpg"]'::jsonb, NULL, 'active', 'open', true, false, 3, 2, 2, '4.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(147, 'Tour Huế 1 ngày từ Hội An hoặc Đà Nẵng', 'vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour', 3, 'Chương trình tour ghép đưa đón tận nơi từ Hội An hoặc Đà Nẵng đi khám phá Cố đô Huế linh thiêng. Trải nghiệm trọn gói vé tham quan các di sản nổi tiếng của vương triều Nguyễn, đắm mình trong danh thắng đèo Hải Vân và vịnh Lăng Cô, thưởng thức ẩm thực Huế đặc sắc.', 'Tour ghép chất lượng cao khám phá di sản Đại Nội Huế, lăng Khải Định và chùa Thiên Mụ.', '[{"time": "07:00 - 07:30", "title": "Đón khách tại khách sạn Hội An hoặc Đà Nẵng", "description": "Đón Quý khách tại khách sạn Hội An hoặc Đà Nẵng, khởi hành đi cố đô Huế. Chúng tôi sẽ đưa Quý khách đến điểm xuất phát và bắt đầu hành trình khám phá Cố đô Huế linh thiêng."}, {"time": "08:30", "title": "Ngắm cảnh Đèo Hải Vân và vịnh Lăng Cô", "description": "Dừng chân ngắm cảnh, chụp hình lưu niệm tại Đèo Hải Vân kỳ vĩ, ghé ngắm cảnh đầm Lập An và vịnh Lăng Cô xanh ngọc. Đây là những danh thắng nổi tiếng của Đà Nẵng và Huế, mang lại cảm giác thư giãn và hứng thú cho Quý khách."}, {"time": "11:00", "title": "Tham quan Lăng Khải Định", "description": "Tham quan Lăng Khải Định - công trình lăng tẩm có thiết kế trang trí nội thất khảm sành sứ tinh xảo bậc nhất. Quý khách sẽ được khám phá kiến trúc độc đáo và tìm hiểu về cuộc sống của vua Khải Định."}, {"time": "12:30", "title": "Dùng bữa trưa đặc sản Huế", "description": "Dùng bữa trưa đặc sản Huế tại nhà hàng địa phương và trải nghiệm ngâm chân thảo dược thư giãn chân sau chặng đi bộ. Quý khách sẽ được thưởng thức ẩm thực Huế đặc sắc và thư giãn trong không gian yên tĩnh."}, {"time": "13:30", "title": "Khám phá hoàng cung Đại Nội Huế", "description": "Khám phá hoàng cung Đại Nội Huế cổ kính, tìm hiểu kiến trúc cung điện và cuộc sống hoàng gia triều Nguyễn xưa. Quý khách sẽ được khám phá các công trình kiến trúc độc đáo và tìm hiểu về lịch sử của Cố đô Huế."}, {"time": "15:00", "title": "Viếng chùa Thiên Mụ", "description": "Viếng chùa Thiên Mụ lịch sử, ngắm tháp Phước Duyên cao vút bên bờ sông Hương lộng gió. Quý khách sẽ được khám phá kiến trúc độc đáo và tìm hiểu về lịch sử của chùa Thiên Mụ."}, {"time": "16:00", "title": "Trở về và kết thúc chương trình", "description": "Lên xe trở về, trả khách tại khách sạn Đà Nẵng hoặc Hội An kết thúc chương trình. Quý khách sẽ được đưa trở về khách sạn sau một ngày khám phá Cố đô Huế linh thiêng."}]'::jsonb, '["Vé tham quan các di sản nổi tiếng của vương triều Nguyễn", "Đưa đón tận nơi từ Hội An hoặc Đà Nẵng", "Ăn trưa đặc sản Huế tại nhà hàng địa phương"]'::jsonb, '["Vé máy bay", "Phí lưu trú tại khách sạn"]'::jsonb, '1350000.00', '0.00', '0.00', 0, '1 ngày', '07:00', 'Đón khách tại khách sạn Hội An hoặc Đà Nẵng, điểm xuất phát là khách sạn nơi Quý khách đang lưu trú.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804900/danangtrip/tours/vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour/tour-023__vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour__p03__vmtravel-hue-city-tour-7.png"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 4, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(148, 'Tour riêng Huế 1 ngày từ Đà Nẵng', 'vmtravel-central-017-hue-day-trip-from-da-nang-private-tour', 3, 'Chuyến tham quan Huế trọn ngày cao cấp được thiết kế riêng tư hoàn toàn với xe du lịch đời mới và hướng dẫn viên riêng. Tự do điều chỉnh lịch trình tham quan Đại Nội, lăng Khải Định, viếng chùa Thiên Mụ, trải nghiệm đi xích lô dạo hoàng thành Huế thanh bình và tận hưởng bữa trưa ẩm thực sân vườn cung đình Huế.', 'Khám phá di sản cố đô Huế trọn ngày từ Đà Nẵng bằng xe riêng, xích lô dạo hoàng thành và ngâm chân thảo dược.', '[{"time": "07:30", "title": "Đón xe riêng và hướng dẫn viên tại khách sạn Đà Nẵng", "description": "Xe riêng và hướng dẫn viên sẽ đón Quý khách tại khách sạn Đà Nẵng và bắt đầu hành trình riêng tư đi Huế. Đây là thời điểm lý tưởng để bắt đầu chuyến tham quan di sản cố đô Huế."}, {"time": "09:00", "title": "Vượt đèo Hải Vân và ngắm vịnh Lăng Cô", "description": "Sau khi vượt qua đèo Hải Vân hùng vĩ, Quý khách sẽ được ngắm vịnh Lăng Cô từ trên cao. Đây là một trong những cảnh đẹp nổi tiếng nhất của Việt Nam. Ghé thăm đầm Lập An để chụp hình phong cảnh hữu tình và tận hưởng không khí trong lành."}, {"time": "11:00", "title": "Tham quan Lăng Khải Định", "description": "Tham quan Lăng Khải Định cổ kính và chiêm ngưỡng nghệ thuật khảm sành sứ độc đáo và tượng đồng dát vàng. Đây là một trong những công trình kiến trúc nổi tiếng nhất của Huế."}, {"time": "12:30", "title": "Trải nghiệm đi xe xích lô dạo hoàng thành Huế", "description": "Trải nghiệm đi xe xích lô dạo quanh hoàng thành Huế cổ kính bóng cây xanh trước khi tiến vào Đại Nội. Đây là một trong những trải nghiệm độc đáo và thú vị nhất của chuyến tham quan."}, {"time": "14:00", "title": "Khám phá Đại Nội Huế", "description": "Khám phá Đại Nội Huế: nghe hướng dẫn viên kể những giai thoại thâm cung bí sử của 13 vị vua nhà Nguyễn. Đây là một trong những trải nghiệm lịch sử và văn hóa độc đáo nhất của chuyến tham quan."}, {"time": "16:00", "title": "Thưởng thức ẩm thực Huế đặc sắc", "description": "Thưởng thức ẩm thực Huế đặc sắc tại nhà hàng sân vườn sang trọng. Món ăn được chế biến từ các nguyên liệu tươi ngon và được phục vụ với phong cách ấm cúng và thân thiện."}, {"time": "17:30", "title": "Viếng chùa Thiên Mụ", "description": "Viếng chùa Thiên Mụ, dạo chơi khuôn viên yên bình bên tháp Phước Duyên trước khi xe đưa Quý khách trở lại Đà Nẵng. Đây là một trong những trải nghiệm tinh thần và yên bình nhất của chuyến tham quan."}]'::jsonb, '["Xe riêng đời mới", "Hướng dẫn viên riêng", "Tham quan Lăng Khải Định", "Trải nghiệm đi xe xích lô dạo hoàng thành Huế", "Khám phá Đại Nội Huế", "Thưởng thức ẩm thực Huế đặc sắc", "Viếng chùa Thiên Mụ"]'::jsonb, '["Phí ăn uống ngoài giờ", "Phí tham quan các điểm du lịch khác"]'::jsonb, '4125000.00', '0.00', '0.00', 0, '1 ngày', '07:30', 'Khách sạn Đà Nẵng, 07:30 sáng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804890/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p01__vmtravel-hue-day-trip.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804890/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p01__vmtravel-hue-day-trip.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804893/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p02__vmtravel-hue-imperial-city-1.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804897/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p03__vmtravel-hue-city-tour-6.png"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 1, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(149, 'Tour Huế 1 ngày từ Đà Nẵng theo nhóm nhỏ', 'vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour', 3, 'Hành trình trọn vẹn khám phá vùng đất di sản cố đô Huế khởi hành từ Đà Nẵng dành cho nhóm nhỏ thân thiện. Thưởng ngoạn đèo Hải Vân hùng vĩ, check-in đầm Lập An, chiêm ngưỡng lăng Khải Định độc đáo, Đại Nội triều Nguyễn thâm nghiêm, viếng chùa Thiên Mụ cổ kính và thư giãn ngâm chân thảo dược hoàng cung.', 'Tour ghép nhóm nhỏ chất lượng cao khám phá cố đô Huế từ Đà Nẵng, ngâm chân thảo dược cung đình và tham quan các di sản hoàng cung.', '[{"time": "07:00 - 07:30", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn Đà Nẵng", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn Đà Nẵng, khởi hành đi Huế. Đây là bước đầu tiên của hành trình khám phá cố đô Huế."}, {"time": "08:30", "title": "Ngắm cảnh đèo Hải Vân hùng vĩ", "description": "Dừng chân ngắm cảnh đèo Hải Vân hùng vĩ - một trong những cung đường ven biển đẹp nhất thế giới. Quý khách sẽ được thưởng ngoạn cảnh quan tuyệt đẹp của đèo Hải Vân."}, {"time": "9:30", "title": "Ghé chụp ảnh đầm Lập An thanh bình", "description": "Ghé chụp ảnh đầm Lập An thanh bình và chiêm ngưỡng vịnh biển Lăng Cô xanh ngắt. Đây là cơ hội để Quý khách chụp ảnh lưu niệm và thư giãn trong không khí thanh bình."}, {"time": "11:00", "title": "Tham quan Lăng Khải Định", "description": "Tham quan Lăng Khải Định - kiệt tác kiến trúc lăng tẩm hoàng gia kết hợp tinh xảo phong cách Đông - Tây. Quý khách sẽ được khám phá kiến trúc độc đáo và lịch sử của lăng Khải Định."}, {"time": "12:30", "title": "Thưởng thức bữa trưa đặc sản Huế", "description": "Thưởng thức bữa trưa đặc sản Huế và tận hưởng dịch vụ ngâm chân thảo dược thiên nhiên thư giãn. Đây là cơ hội để Quý khách thưởng thức ẩm thực Huế và thư giãn trong không khí yên tĩnh."}, {"time": "13:30", "title": "Khám phá Đại Nội Huế", "description": "Khám phá Đại Nội Huế - kinh thành hoàng gia triều Nguyễn cổ kính với Ngọ Môn, điện Thái Hòa và Thế Miếu. Quý khách sẽ được khám phá kiến trúc và lịch sử của Đại Nội Huế."}, {"time": "15:00", "title": "Viếng chùa Thiên Mụ", "description": "Viếng chùa Thiên Mụ - ngôi chùa cổ kính linh thiêng nhất cố đô bên dòng sông Hương thơ mộng. Quý khách sẽ được khám phá kiến trúc và lịch sử của chùa Thiên Mụ."}, {"time": "16:00", "title": "Khởi hành về lại Đà Nẵng", "description": "Khởi hành về lại Đà Nẵng qua hầm Hải Vân, xe đưa Quý khách về lại khách sạn kết thúc tour. Đây là bước cuối cùng của hành trình khám phá cố đô Huế."}]'::jsonb, '["Xe đưa đón, hướng dẫn viên, bữa trưa đặc sản Huế, dịch vụ ngâm chân thảo dược thiên nhiên"]'::jsonb, '["Vé vào cửa các điểm tham quan, đồ uống, chi phí cá nhân"]'::jsonb, '1225000.00', '0.00', '0.00', 0, '1 ngày', '07:00', 'Khách sạn Đà Nẵng, 07:00 sáng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804883/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p02__vmtravel-khai-dinh-tomb-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 5, '4.60', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(150, 'Tour Huế DMZ Tìm hiểu dấu ấn lịch sử', 'vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour', 3, 'Chuyến du hành ngược thời gian tìm hiểu về thời kỳ kháng chiến cứu nước hào hùng tại vùng phi quân sự DMZ Quảng Trị. Tour đưa du khách ghé thăm các địa danh lịch sử nổi tiếng như sông Bến Hải, cầu Hiền Lương, căn cứ quân sự Khe Sanh huyền thoại và địa đạo đất sét Vịnh Mốc kỳ vĩ - kiệt tác ngầm biểu tượng cho ý chí kiên cường chịu đựng của quân dân ta.', 'Hành trình hào hùng về lại chiến trường xưa Quảng Trị: Cầu Hiền Lương, sông Bến Hải, địa đạo Vịnh Mốc và căn cứ Khe Sanh.', '[{"time": "07:00", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn ở Huế", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn ở Huế và khởi hành đi Quảng Trị để tham quan vùng phi quân sự DMZ."}, {"time": "09:00", "title": "Dừng chân tham quan Cầu Đakrông", "description": "Cầu Đakrông là điểm nút giao thông chiến lược trên tuyến đường mòn Hồ Chí Minh lịch sử. Du khách sẽ dừng chân tham quan và hiểu thêm về tầm quan trọng của cầu này trong quá khứ."}, {"time": "11:00", "title": "Khám phá Căn cứ quân sự Khe Sanh", "description": "Căn cứ quân sự Khe Sanh là một trong những căn cứ quân sự quan trọng nhất của quân đội Việt Nam trong chiến tranh. Du khách sẽ khám phá các khí tài chiến tranh trưng bày ngoài trời và hiểu thêm về lịch sử của căn cứ này."}, {"time": "13:00", "title": "Dùng bữa trưa tại Đông Hà", "description": "Sau khi tham quan Căn cứ quân sự Khe Sanh, du khách sẽ dùng bữa trưa tại Đông Hà, một trong những thành phố quan trọng nhất của Quảng Trị."}, {"time": "14:30", "title": "Tham quan cụm di tích đôi bờ Hiền Lương - Sông Bến Hải", "description": "Cụm di tích đôi bờ Hiền Lương - Sông Bến Hải là một trong những địa danh lịch sử nổi tiếng nhất của Quảng Trị. Du khách sẽ tham quan và hiểu thêm về lịch sử của vùng phi quân sự DMZ."}, {"time": "16:30", "title": "Khám phá địa đạo Vịnh Mốc", "description": "Địa đạo Vịnh Mốc là một hệ thống hầm ngầm kỳ vĩ dưới lòng đất, nơi sinh sống của cả một ngôi làng trong bom đạn chiến tranh. Du khách sẽ khám phá và hiểu thêm về ý chí kiên cường chịu đựng của quân dân ta."}, {"time": "18:00", "title": "Xe đưa Quý khách trở lại Huế", "description": "Sau khi tham quan địa đạo Vịnh Mốc, xe sẽ đưa Quý khách trở lại Huế, kết thúc hành trình lịch sử ý nghĩa."}]'::jsonb, '["Xe và hướng dẫn viên", "Ăn trưa tại Đông Hà", "Tham quan các địa danh lịch sử"]'::jsonb, '["Ăn sáng và tối", "Phí tham quan các địa danh lịch sử"]'::jsonb, '1250000.00', '0.00', '0.00', 0, '1 ngày', '07:00', 'Khách sạn ở Huế, 07:00 sáng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804870/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p01__vmtravel-hue-dmz-tour-3.png', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804870/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p01__vmtravel-hue-dmz-tour-3.png", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804873/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p02__vmtravel-hue-dmz-tour.png", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804877/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p03__vmtravel-hue-dmz-tour-1.png"]'::jsonb, NULL, 'active', 'open', true, false, 3, 0, 6, '4.67', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(151, 'Tour Cù Lao Chàm lặn ngắm san hô từ Hội An hoặc Đà Nẵng', 'vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang', 4, 'Tour du lịch Cù Lao Chàm chất lượng cao đưa đón từ Đà Nẵng hoặc Hội An. Tận hưởng vẻ đẹp nguyên sơ của đảo với biển xanh cát trắng, trải nghiệm lặn biển ngắm rặng san hô đa sắc, tìm hiểu di tích văn hóa Chăm cổ xưa và thưởng thức ẩm thực bản địa tươi ngon.', 'Khám phá Cù Lao Chàm với biển xanh cát trắng, lặn ngắm san hô đa sắc và ẩm thực bản địa tươi ngon.', '[{"time": "07:30 - 08:00", "title": "Đón khách tại khách sạn Đà Nẵng hoặc Hội An", "description": "Xe và hướng dẫn viên đón Quý khách tại khách sạn Đà Nẵng hoặc Hội An, bắt đầu hành trình khám phá Cù Lao Chàm."}, {"time": "08:30", "title": "Lên ca nô cao tốc", "description": "Lên ca nô cao tốc, tận hưởng làn gió mát lạnh trên hành trình 30 phút ra đảo Cù Lao Chàm."}, {"time": "09:00", "title": "Tham quan Khu bảo tồn biển", "description": "Cập bến Bãi Làng, tham quan Khu bảo tồn biển, nơi bạn có thể tìm hiểu về hệ sinh thái biển và các loài động vật quý hiếm."}, {"time": "09:30", "title": "Tham quan giếng cổ Chăm Pa", "description": "Tham quan giếng cổ Chăm Pa, một trong những di tích văn hóa Chăm cổ xưa và quan trọng nhất trên đảo."}, {"time": "10:00", "title": "Tham quan chùa cổ Hải Tạng", "description": "Tham quan chùa cổ Hải Tạng, một ngôi chùa cổ kính và đẹp mắt trên đảo."}, {"time": "10:30", "title": "Tham quan chợ hải sản Tân Hiệp", "description": "Tham quan chợ hải sản Tân Hiệp, nơi bạn có thể tìm hiểu về cuộc sống của người dân trên đảo và mua sắm các sản phẩm hải sản tươi ngon."}, {"time": "11:30", "title": "Điểm lặn ngắm san hô", "description": "Ca nô đưa đoàn đến điểm lặn ngắm san hô, trang bị kính lặn và áo phao khám phá thế giới sinh vật biển rực rỡ dưới lòng đại dương."}, {"time": "12:00", "title": "Thưởng thức bữa trưa hải sản", "description": "Thưởng thức bữa trưa hải sản và các món đặc sản đảo tại nhà hàng ven biển Bãi Chồng."}, {"time": "13:00", "title": "Tự do tắm biển", "description": "Tự do tắm biển, nằm thư giãn trên bãi cát trắng mịn dưới bóng dừa râm mát."}, {"time": "13:30", "title": "Lên ca nô cao tốc quay về", "description": "Lên ca nô cao tốc quay về lại cảng Cửa Đại."}, {"time": "14:30 - 15:00", "title": "Đón khách về lại khách sạn", "description": "Xe đưa Quý khách về lại khách sạn kết thúc chuyến tham quan thú vị."}]'::jsonb, '["Xe đưa đón từ Đà Nẵng hoặc Hội An", "Hướng dẫn viên chuyên nghiệp", "Bữa trưa hải sản", "Kính lặn và áo phao", "Tham quan các điểm du lịch trên đảo"]'::jsonb, '["Phí ăn uống ngoài giờ", "Phí mua sắm", "Phí tham gia các hoạt động khác"]'::jsonb, '750000.00', '0.00', '0.00', 0, '6 giờ', '07:30', 'Đón khách tại khách sạn Đà Nẵng hoặc Hội An', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804770/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p01__vmtravel-snockerling-in-cham-island.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804770/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p01__vmtravel-snockerling-in-cham-island.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804773/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p02__vmtravel-cham-island-tour-from-da-nang.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804777/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p03__vmtravel-cu-lao-cham.jpg"]'::jsonb, NULL, 'active', 'open', false, true, 3, 0, 3, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(152, 'Tour Cù Lao Chàm tham quan và lặn ngắm san hô', 'recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel', 4, 'Khám phá thiên đường đảo xanh Cù Lao Chàm được UNESCO công nhận là Khu dự trữ sinh quyển thế giới. Trải nghiệm cảm giác lướt sóng ca nô cao tốc, tham quan các di tích cổ xưa, tìm hiểu đời sống ngư dân trên đảo, thỏa sức tắm biển, lặn ngắm san hô sắc màu và thưởng thức bữa trưa hải sản tươi sống đánh bắt tại chỗ.', 'Chuyến du ngoạn đảo xanh Cù Lao Chàm bằng ca nô cao tốc, lặn ngắm san hô kỳ thú và thưởng thức hải sản tươi ngon.', '[{"time": "08:00", "title": "Xe đón Quý khách tại khách sạn", "description": "Xe sẽ đón Quý khách tại khách sạn và di chuyển đến cảng Cửa Đại (Hội An) để bắt đầu hành trình khám phá Cù Lao Chàm."}, {"time": "Lên ca nô cao tốc", "title": "Lướt sóng ca nô cao tốc đến đảo Cù Lao Chàm", "description": "Quý khách sẽ lên ca nô cao tốc và lướt sóng gió biển khơi đến đảo Cù Lao Chàm. Đây là một trải nghiệm tuyệt vời để cảm nhận được sức mạnh của biển khơi."}, {"time": "Tham quan khu bảo tồn biển", "title": "Tham quan khu bảo tồn biển", "description": "Sau khi đến đảo, Quý khách sẽ tham quan khu bảo tồn biển để tìm hiểu về hệ sinh thái biển và các loài động vật quý hiếm trên đảo."}, {"time": "Tham quan chùa Hải Tạng cổ kính", "title": "Tham quan chùa Hải Tạng cổ kính", "description": "Tiếp theo, Quý khách sẽ tham quan chùa Hải Tạng cổ kính, một ngôi chùa lịch sử trên đảo Cù Lao Chàm."}, {"time": "Tham quan chợ Tân Hiệp", "title": "Tham quan chợ Tân Hiệp", "description": "Sau đó, Quý khách sẽ tham quan chợ Tân Hiệp, nơi bán các sản phẩm địa phương như hải sản, trái cây và thủ công mỹ nghệ."}, {"time": "Tắm biển và lặn ngắm san hô", "title": "Tắm biển và lặn ngắm san hô", "description": "Tiếp theo, Quý khách sẽ tắm biển và lặn ngắm san hô bằng kính lặn cơ bản (30 phút) tại bãi san hô đẹp. Đây là một trải nghiệm tuyệt vời để khám phá thế giới dưới biển."}, {"time": "Thưởng thức bữa trưa hải sản", "title": "Thưởng thức bữa trưa hải sản", "description": "Sau đó, Quý khách sẽ thưởng thức bữa trưa hải sản tươi ngon đặc sản đảo tại nhà hàng Bãi Ông hoặc Bãi Chồng."}, {"time": "14:00", "title": "Lên ca nô trở lại đất liền", "description": "Cuối cùng, Quý khách sẽ lên ca nô trở lại đất liền và xe sẽ đưa Quý khách về lại khách sạn kết thúc tour."}]'::jsonb, '["Xe đón và đưa Quý khách tại khách sạn", "Ca nô cao tốc đến đảo Cù Lao Chàm", "Tham quan khu bảo tồn biển", "Tham quan chùa Hải Tạng cổ kính", "Tham quan chợ Tân Hiệp", "Tắm biển và lặn ngắm san hô", "Thưởng thức bữa trưa hải sản"]'::jsonb, '["Phí ăn uống ngoài giờ", "Phí mua sắm", "Phí tham quan các địa điểm khác"]'::jsonb, '765500.00', '0.00', '0.00', 0, '6 giờ', '08:00', 'Xe sẽ đón Quý khách tại khách sạn và di chuyển đến cảng Cửa Đại (Hội An) để bắt đầu hành trình khám phá Cù Lao Chàm.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804761/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p01__venus-cu-lao-cham-2-e1700123421497.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804761/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p01__venus-cu-lao-cham-2-e1700123421497.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804764/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p02__pexels-5116361.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804767/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p03__pexels-27506369.jpg"]'::jsonb, NULL, 'active', 'open', false, true, 3, 0, 6, '4.67', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(153, 'Tour ẩm thực đường phố Huế', 'vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45', 6, 'Khám phá thế giới ẩm thực phong phú và tinh tế của cố đô Huế qua chuyến đi thực tế. Cùng hướng dẫn viên bản địa ghé thăm các quán ăn truyền thống lâu đời, thưởng thức các loại bánh Huế mộc mạc, tô bún bò Huế cay nồng chuẩn vị và các món chè ngọt mát rượi độc đáo.', 'Hành trình đi bộ và xích lô trải nghiệm ẩm thực đường phố Huế: bánh bèo nậm lọc, bún bò Huế, chè Huế và chợ Đông Ba.', '[{"time": "17:00", "title": "Hướng dẫn viên đón Quý khách tại khách sạn trung tâm Huế", "description": "Hướng dẫn viên sẽ đón Quý khách tại khách sạn trung tâm Huế và bắt đầu hành trình ẩm thực đường phố Huế. Chúng tôi sẽ đi bộ qua các con phố sầm uất và khám phá không khí ẩm thực của cố đô Huế."}, {"time": "17:30", "title": "Ghé Chợ Đông Ba", "description": "Chúng tôi sẽ ghé thăm Chợ Đông Ba, một trong những chợ nổi tiếng nhất của Huế. Tại đây, Quý khách sẽ được thử các món ăn nhẹ dân dã của chợ và cảm nhận không khí sầm uất của chợ chiều tối."}, {"time": "18:00", "title": "Dạo bước vượt cầu Trường Tiền", "description": "Chúng tôi sẽ dạo bước qua cầu Trường Tiền, một trong những cầu lịch sử nổi tiếng của Huế. Quý khách sẽ được ngắm nhìn dòng sông Hương êm đềm lộng gió dưới ánh đèn đêm lung linh."}, {"time": "18:30", "title": "Thưởng thức bánh Huế truyền thống", "description": "Chúng tôi sẽ thưởng thức khay bánh Huế truyền thống tại quán bánh nổi tiếng: Bánh Bèo, Bánh Nậm, Bánh Bột Lọc dai ngon. Quý khách sẽ được cảm nhận hương vị mộc mạc và tinh tế của bánh Huế."}, {"time": "19:30", "title": "Trải nghiệm Bún Bò Huế", "description": "Chúng tôi sẽ trải nghiệm tô Bún Bò Huế thơm phức, nước dùng đậm đà hương vị sả ruốc tại quán ăn gia truyền địa phương. Quý khách sẽ được cảm nhận hương vị cay nồng và chuẩn vị của Bún Bò Huế."}, {"time": "20:30", "title": "Tráng miệng với Chè Huế", "description": "Chúng tôi sẽ tráng miệng thanh mát với các món Chè Huế đa dạng sắc màu tại gánh chè chợ đêm. Quý khách sẽ được cảm nhận hương vị ngọt mát và độc đáo của Chè Huế."}, {"time": "21:30", "title": "Kết thúc hành trình", "description": "Chúng tôi sẽ kết thúc hành trình ẩm thực đường phố Huế và đưa Quý khách đi dạo ngắm cảnh đêm hoặc đưa về lại khách sạn nghỉ ngơi."}]'::jsonb, '["Hướng dẫn viên bản địa", "Thực phẩm và đồ uống", "Xích lô"]'::jsonb, '["Phí khách sạn", "Phí ăn uống ngoài hành trình"]'::jsonb, '1125000.00', '0.00', '0.00', 0, '5 giờ', '17:00', 'Khách sạn trung tâm Huế', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804911/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p01__vmtravel-hue-strees-food-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804911/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p01__vmtravel-hue-strees-food-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804914/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p02__vmtravel-hu-food-tour-from-danang.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804866/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p03__vmtravel-cyclo-in-hue.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 6, '4.67', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(154, 'Tour lớp nấu ăn Huế từ chợ địa phương đến bàn ăn', 'vmtravel-central-016-hue-cooking-class-tour-from-market-to-table', 6, 'Khám phá chiều sâu văn hóa ẩm thực xứ Huế thông qua lớp học nấu ăn thực tế. Từ hành trình đi xích lô dạo chợ Đông Ba chọn mua gia vị đặc trưng đến việc học nấu các món ăn cầu kỳ tại một nhà vườn truyền thống thanh tịnh, mang lại trải nghiệm đáng nhớ cho tâm hồn ăn uống.', 'Khám phá văn hóa ẩm thực Huế qua lớp học nấu ăn thực tế', '[{"time": "08:30", "title": "Đón khách tại khách sạn và di chuyển đến Chợ Đông Ba", "description": "Đón Quý khách tại khách sạn bằng xe xích lô hoài cổ. Hành trình di chuyển đến Chợ Đông Ba sầm uất sẽ mang lại cảm giác thú vị và độc đáo. Tại chợ, Quý khách sẽ được dạo quanh cùng hướng dẫn viên, tìm hiểu nguyên liệu ẩm thực địa phương và chọn mua thực phẩm tươi ngon cho buổi học."}, {"time": "10:00", "title": "Di chuyển đến nhà vườn Huế cổ kính", "description": "Di chuyển bằng thuyền rồng hoặc xích lô đến nhà vườn Huế cổ kính - không gian tổ chức lớp nấu ăn. Nhà vườn này sẽ mang lại cho Quý khách cảm giác yên bình và thanh tịnh, tạo điều kiện thuận lợi cho việc học nấu ăn."}, {"time": "10:30", "title": "Thưởng thức trà cung đình và nghe giới thiệu triết lý ẩm thực Huế", "description": "Thưởng thức trà cung đình đón mừng, nghe đầu bếp giới thiệu triết lý ẩm thực Huế. Đây là bước quan trọng để Quý khách hiểu về văn hóa ẩm thực Huế và chuẩn bị cho việc học nấu ăn."}, {"time": "11:00", "title": "Thực hành chế biến món ăn Huế truyền thống", "description": "Tự tay thực hành chế biến 3-4 món ăn Huế truyền thống (như vả trộn, chả giò, bánh bèo, bánh bột lọc) dưới sự chỉ dẫn của chuyên gia ẩm thực. Đây là bước thú vị và sáng tạo, mang lại cho Quý khách cảm giác tự hào về khả năng nấu ăn của mình."}, {"time": "12:30", "title": "Thưởng thức bữa trưa do chính tay mình chuẩn bị", "description": "Thưởng thức bữa trưa do chính tay mình chuẩn bị trong không gian sân vườn mát mẻ. Đây là bước cuối cùng của tour, mang lại cho Quý khách cảm giác hài lòng và thỏa mãn."}, {"time": "13:00", "title": "Xích lô đưa Quý khách về lại khách sạn", "description": "Xích lô đưa Quý khách về lại khách sạn, kết thúc tour lớp nấu ăn Huế từ chợ địa phương đến bàn ăn."}]'::jsonb, '["Xe xích lô di chuyển đến Chợ Đông Ba", "Thực phẩm tươi ngon cho buổi học", "Trà cung đình", "Chuyên gia ẩm thực hướng dẫn", "Bữa trưa do chính tay mình chuẩn bị"]'::jsonb, '["Rượu và các loại đồ uống có cồn", "Các món ăn không được liệt kê trong chương trình"]'::jsonb, '1125000.00', '0.00', '0.00', 0, '6 giờ', '08:30', 'Đón khách tại khách sạn, xe xích lô sẽ chờ sẵn để đưa Quý khách đến Chợ Đông Ba.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804860/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p01__vmtravel-hue-cooking-class.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804860/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p01__vmtravel-hue-cooking-class.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804863/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p02__vmtravel-cooking-class-at-madam-thu.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804866/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p03__vmtravel-cyclo-in-hue.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 2, '4.50', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(155, 'Tour Huế Đạp Xe, Nông Trại Hữu Cơ và Lớp Nấu Ăn', 'vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class', 6, 'Trải nghiệm du lịch sinh thái và văn hóa ẩm thực sâu sắc tại Huế. Rời xa phố thị ồn ào để đạp xe qua những nẻo đường làng thơ mộng, chiêm ngưỡng Cầu ngói Thanh Toàn lịch sử, hóa thân làm nông dân thực thụ tại vườn rau hữu cơ và học cách chế biến những món ăn truyền thống đặc trưng của Huế từ nguyên liệu thô tự mua tại chợ quê.', 'Đạp xe qua miền quê xứ Huế thanh bình, làm nông dân hữu cơ và học nấu đặc sản Huế.', '[{"time": "08:00", "title": "Gặp Hướng Dẫn Viên và Nhận Xe Đạp", "description": "Gặp hướng dẫn viên tại Huế, nhận xe đạp và bắt đầu hành trình đạp xe thong dông qua những ngôi làng quê yên bình, đồng lúa xanh ngát. Đây là cơ hội để bạn trải nghiệm không khí thanh bình của miền quê Huế và bắt đầu hành trình khám phá."}, {"time": "08:30", "title": "Tham Quan Cầu Ngói Thanh Toàn", "description": "Ghé thăm Cầu ngói Thanh Toàn - cây cầu gỗ mái ngói cổ xưa nổi tiếng và tham quan bảo tàng nông cụ địa phương. Bạn sẽ được biết thêm về lịch sử và văn hóa của cây cầu này và có cơ hội tham quan các loại nông cụ truyền thống."}, {"time": "09:30", "title": "Nông Trại Hữu Cơ", "description": "Đạp xe đến nông trại hữu cơ, tìm hiểu phương pháp gieo trồng truyền thống và cùng người nông dân trải nghiệm làm vườn. Bạn sẽ được biết thêm về cách trồng rau hữu cơ và có cơ hội trải nghiệm làm vườn thực thụ."}, {"time": "10:30", "title": "Lớp Học Nấu Ăn", "description": "Tham gia lớp học nấu ăn: ghé chợ quê chọn mua nguyên liệu tươi sạch, tự tay chế biến các món đặc sản Huế như bánh khoái, nem lụi dưới sự hướng dẫn của đầu bếp. Bạn sẽ được học cách chế biến các món ăn truyền thống đặc trưng của Huế và có cơ hội thưởng thức thành phẩm."}, {"time": "12:30", "title": "Thưởng Thức Bữa Trưa", "description": "Thưởng thức thành phẩm bữa trưa tự nấu và đạp xe trở về điểm xuất phát, đưa Quý khách về khách sạn nghỉ ngơi. Đây là cơ hội để bạn thưởng thức các món ăn truyền thống đặc trưng của Huế mà bạn đã học cách chế biến."}]'::jsonb, '["Xe đạp, hướng dẫn viên, nguyên liệu nấu ăn, bữa trưa"]'::jsonb, '["Đồ uống, các chi phí cá nhân"]'::jsonb, '1500000.00', '0.00', '0.00', 0, '8 giờ', '08:00', 'Gặp hướng dẫn viên tại Huế, gần trung tâm thành phố', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804851/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p01__vmtravel-hue-cycling-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804851/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p01__vmtravel-hue-cycling-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804854/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p02__vmtravel-hue-eco-tour-farm.webp", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804857/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p03__vmtravel-hue-bicycle-tour.webp"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 3, '4.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(156, 'Tour riêng khám phá Đà Nẵng trong ngày', 'vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour', 9, 'Hành trình riêng tư được thiết kế linh hoạt mang đến trải nghiệm thoải mái nhất cho du khách. Tự do khám phá vẻ đẹp tự nhiên của Ngũ Hành Sơn, văn hóa Champa tại Bảo tàng Chăm cổ kính, mua sắm Chợ Hàn, viếng chùa Linh Ứng và ngắm cảnh biển xanh cát trắng tại Mỹ Khê.', 'Hành trình riêng tư trọn ngày khám phá mọi danh lam thắng cảnh tiêu biểu nhất của thành phố Đà Nẵng.', '[{"time": "08:00", "title": "Đón xe riêng và hướng dẫn viên tại khách sạn", "description": "Xe riêng và hướng dẫn viên sẽ đón Quý khách tại khách sạn và bắt đầu hành trình khám phá Đà Nẵng trong ngày. Đây là thời điểm lý tưởng để bắt đầu hành trình, khi Quý khách còn đầy sức sống và năng lượng."}, {"time": "08:30", "title": "Khám phá Ngũ Hành Sơn", "description": "Sẽ đến Ngũ Hành Sơn, một trong những danh lam thắng cảnh nổi tiếng nhất của Đà Nẵng. Quý khách sẽ được dạo quanh các động đá tự nhiên kỳ vĩ và viếng chùa Tam Thai, nơi thờ tự Phật giáo và mang đến cảm giác yên bình và thanh thản."}, {"time": "10:00", "title": "Làng nghề điêu khắc đá Non Nước", "description": "Sẽ đến làng nghề điêu khắc đá Non Nước, nơi các nghệ nhân tài năng sẽ giới thiệu cách tạo tác đá độc đáo và độc đáo. Quý khách sẽ được tận mắt chứng kiến quá trình tạo tác đá và có thể mua sắm những sản phẩm độc đáo này."}, {"time": "10:30", "title": "Bảo tàng Điêu khắc Chăm cổ kính", "description": "Sẽ đến Bảo tàng Điêu khắc Chăm cổ kính, nơi trưng bày các tác phẩm điêu khắc Chăm cổ kính và mang đến hiểu biết về văn hóa Champa. Quý khách sẽ được tham quan các tác phẩm điêu khắc và có thể mua sắm những sản phẩm độc đáo này."}, {"time": "13:30", "title": "Chợ Hàn", "description": "Sẽ đến Chợ Hàn, một trong những chợ nổi tiếng nhất của Đà Nẵng. Quý khách sẽ được mua sắm những sản vật địa phương phong phú và độc đáo, từ quần áo đến đồ lưu niệm."}, {"time": "14:30", "title": "Chùa Linh Ứng Sơn Trà", "description": "Sẽ đến Chùa Linh Ứng Sơn Trà, nơi thờ tự Phật giáo và mang đến cảm giác yên bình và thanh thản. Quý khách sẽ được viếng chùa và cầu bình an bên tượng Phật Bà Quan Thế Âm cao nhất Việt Nam."}, {"time": "16:00", "title": "Bãi biển Mỹ Khê", "description": "Sẽ đến Bãi biển Mỹ Khê, một trong những bãi biển quyến rũ nhất hành tinh. Quý khách sẽ được thư giãn, đi dạo và chụp hình lưu niệm trên bãi biển này trước khi về lại khách sạn."}]'::jsonb, '["Xe riêng", "Hướng dẫn viên", "Ăn trưa tại nhà hàng đặc sản địa phương", "Mua sắm tại Chợ Hàn"]'::jsonb, '["Ăn sáng và tối", "Rượu và các loại đồ uống có cồn"]'::jsonb, '3450000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Đón xe riêng và hướng dẫn viên tại khách sạn', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804798/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p01__vmtravel-da-nang-city-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804798/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p01__vmtravel-da-nang-city-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804783/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p02__vmtravel-marble-mountains.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804801/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p03__vmtravel-linh-ung-pagoda-1.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 4, '4.25', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(157, 'Tour Đà Nẵng từ cảng Tiên Sa kết hợp mua sắm', 'vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping', 9, 'Hành trình city tour Đà Nẵng chất lượng cao được thiết kế khớp thời gian tàu cập cảng Tiên Sa. Trải nghiệm trọn vẹn văn hóa, lịch sử và thắng cảnh tiêu biểu của thành phố đáng sống: danh thắng Ngũ Hành Sơn cổ kính, bảo tàng cổ vật Chăm sâu lắng, chợ Hàn mua sắm nhộn nhịp và chùa Linh Ứng Sơn Trà linh thiêng.', 'Tour city khám phá Đà Nẵng đón từ cảng Tiên Sa dành cho khách tàu biển', '[{"time": "08:00", "title": "Xe đón Quý khách tại cảng Tiên Sa", "description": "Xe sẽ đón Quý khách tại cảng Tiên Sa (trong hoặc ngoài cổng cảng) với bảng tên riêng, khởi hành đi tham quan thành phố Đà Nẵng."}, {"time": "09:00", "title": "Tham quan Ngũ Hành Sơn", "description": "Tham quan quần thể núi đá vôi gắn liền với truyền thuyết, viếng chùa cổ và khám phá động Huyền Không."}, {"time": "10:30", "title": "Tìm hiểu nghề điêu khắc đá truyền thống", "description": "Tìm hiểu nghề điêu khắc đá truyền thống tại Làng đá Mỹ nghệ Non Nước lâu đời."}, {"time": "11:00", "title": "Tham quan Bảo tàng Điêu khắc Chăm", "description": "Tham quan Bảo tàng Điêu khắc Chăm - nơi lưu giữ bộ sưu tập hiện vật điêu khắc Champa vô giá lớn nhất thế giới."}, {"time": "12:30", "title": "Thưởng thức bữa trưa đặc sản Đà Nẵng", "description": "Thưởng thức bữa trưa đặc sản Đà Nẵng tại nhà hàng địa phương sạch sẽ, tiện nghi."}, {"time": "14:00", "title": "Tham quan mua sắm đặc sản", "description": "Tham quan mua sắm đặc sản làm quà tại Chợ Hàn - ngôi chợ sầm uất và lâu đời nhất thành phố."}, {"time": "15:30", "title": "Ghé Bán đảo Sơn Trà", "description": "Ghé Bán đảo Sơn Trà, viếng chùa Linh Ứng Bãi Bụt và ngắm toàn cảnh vịnh Đà Nẵng xinh đẹp từ trên cao."}, {"time": "16:30", "title": "Xe đưa Quý khách trở lại cảng Tiên Sa", "description": "Xe đưa Quý khách trở lại cảng Tiên Sa trước giờ tàu rời bến tối thiểu 1.5 giờ, kết thúc chương trình."}]'::jsonb, '["Xe đưa đón, hướng dẫn viên, bữa trưa đặc sản Đà Nẵng, tham quan các điểm du lịch"]'::jsonb, '["Vé vào cửa các điểm du lịch, thức ăn và nước uống ngoài giờ trưa"]'::jsonb, '2050000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Xe sẽ đón Quý khách tại cảng Tiên Sa (trong hoặc ngoài cổng cảng) với bảng tên riêng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804789/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p01__vmtravel-da-nang-city-tour-1.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804789/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p01__vmtravel-da-nang-city-tour-1.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804792/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p02__vmtravel-da-nang-full-day-trip.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804795/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p03__vmtravel-cham-mesurm.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 2, 2, '5.00', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(158, 'Tour Khám Phá Thành Phố Đà Nẵng Theo Nhóm', 'vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel', 9, 'Chuyến tham quan nửa ngày lý tưởng để khám phá những nét đẹp nổi bật của thành phố Đà Nẵng. Từ các hang động huyền bí và chùa cổ kính tại Ngũ Hành Sơn đến bức tượng Phật Bà khổng lồ trên bán đảo Sơn Trà xanh mát, kết thúc bằng một vòng mua sắm tại Chợ Hàn và thưởng thức ẩm thực địa phương đặc sắc.', 'Khám phá các biểu tượng danh thắng nổi tiếng nhất Đà Nẵng: Ngũ Hành Sơn, chùa Linh Ứng Sơn Trà và chợ Hàn.', '[{"time": "08:45 - 09:15", "title": "Đón Quý Khách Tại Các Khách Sạn Khu Vực Trung Tâm Đà Nẵng", "description": "Đón Quý khách tại các khách sạn khu vực trung tâm Đà Nẵng, bắt đầu hành trình city tour khám phá thành phố đáng sống."}, {"time": "09:15 - 10:30", "title": "Tham Quan Danh Thắng Ngũ Hành Sơn", "description": "Tham quan quần thể 5 ngọn núi đá vôi linh thiêng, khám phá các hang động kỳ bí và chùa cổ kính tại Ngũ Hành Sơn. Khám phá các tác phẩm điêu khắc đá tinh xảo của nghệ nhân địa phương tại Làng đá mỹ nghệ Non Nước dưới chân núi."}, {"time": "10:30 - 11:00", "title": "Ghé Thăm Làng Đá Mỹ Nghệ Non Nước", "description": "Chiêm ngưỡng các tác phẩm điêu khắc đá tinh xảo của nghệ nhân địa phương tại Làng đá mỹ nghệ Non Nước dưới chân núi."}, {"time": "11:00 - 12:15", "title": "Tham Quan Chùa Linh Ứng Bán Đảo Sơn Trà", "description": "Tham quan chùa Linh Ứng Bán đảo Sơn Trà, chiêm ngưỡng tượng Phật Bà Quan Âm cao 67m hướng ra biển cả. Khám phá vẻ đẹp tự nhiên của bán đảo Sơn Trà với các loài thực vật và động vật quý hiếm."}, {"time": "12:15 - 13:15", "title": "Ghé Chợ Hàn Nhộn Nhịp", "description": "Ghé Chợ Hàn nhộn nhịp, tìm hiểu cuộc sống thường nhật của người dân và mua sắm quà lưu niệm đặc sản. Khám phá các sản phẩm địa phương và thưởng thức ẩm thực đường phố tại Chợ Hàn."}, {"time": "13:15 - 13:30", "title": "Thưởng Thức Bữa Trưa Với Các Món Đặc Sản", "description": "Thưởng thức bữa trưa với các món đặc sản ẩm thực Đà Nẵng tại nhà hàng địa phương. Khám phá các món ăn địa phương và thưởng thức không khí ẩm thực tại Đà Nẵng."}, {"time": "13:30", "title": "Kết Thúc Chuyến Tham Quan", "description": "Xe đưa Quý khách về lại khách sạn, kết thúc chuyến tham quan thành phố đáng sống."}]'::jsonb, '["Vé tham quan các danh thắng", "Bữa trưa tại nhà hàng địa phương", "Dịch vụ hướng dẫn viên"]'::jsonb, '["Phí ăn uống ngoài giờ", "Phí mua sắm tại Chợ Hàn"]'::jsonb, '800000.00', '0.00', '0.00', 0, '6 giờ', '08:45', 'Đón Quý khách tại các khách sạn khu vực trung tâm Đà Nẵng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804780/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p01__vmtravel-danang-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804780/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p01__vmtravel-danang-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804783/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p02__vmtravel-marble-mountains.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804786/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p03__vmtravel-my-khe-beach.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 4, '3.75', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(159, 'Tour Golf Đà Nẵng 6 Ngày 5 Đêm Cao Cấp', 'vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds', 30, 'Hành trình nghỉ dưỡng kết hợp gôn cao cấp dài ngày. Gôn thủ sẽ được chinh phục 4 sân gôn đỉnh cao của khu vực: BRG Đà Nẵng, Vinpearl Nam Hội An, Bà Nà Hills và Laguna Lăng Cô. Dịch vụ trọn gói bao gồm lưu trú khách sạn 4-5 sao, đưa đón riêng biệt, xe điện buggy và caddy chuyên nghiệp tại mỗi sân.', 'Kỳ nghỉ dưỡng và chơi gôn 6 ngày trải nghiệm 4 sân gôn đỉnh cao hàng đầu miền Trung', '[{"time": "08:00", "title": "Ngày 1: Đón Quý khách tại sân bay Đà Nẵng", "description": "Đón quý khách tại sân bay Đà Nẵng, đưa về khách sạn nhận phòng nghỉ ngơi, tự do dạo phố để khám phá thành phố biển xinh đẹp này."}, {"time": "07:00", "title": "Ngày 2: Điểm tâm sáng và chơi gôn tại BRG Danang Golf Resort", "description": "Điểm tâm sáng tại khách sạn, sau đó di chuyển đến sân golf BRG Danang Golf Resort để chơi 18 hố gôn đẳng cấp. Chiều tham quan danh thắng Ngũ Hành Sơn, một trong những điểm du lịch nổi tiếng của Đà Nẵng."}, {"time": "07:00", "title": "Ngày 3: Chơi gôn tại Vinpearl Golf Nam Hội An", "description": "Khởi hành đi chơi gôn tại Vinpearl Golf Nam Hội An, một trong những sân golf hàng đầu của Việt Nam. Chiều tham quan VinWonders Nam Hội An và River Safari, nơi bạn có thể khám phá thế giới động vật và tận hưởng không khí trong lành."}, {"time": "07:00", "title": "Ngày 4: Trải nghiệm gôn tại sân gôn Bà Nà Hills", "description": "Trải nghiệm 18 hố gôn tại sân gôn Bà Nà Hills Golf Club, ẩn mình dưới chân núi. Tối đi thuyền rồng ngắm sông Hàn ăn tối, một trải nghiệm không thể bỏ qua khi đến Đà Nẵng."}, {"time": "07:00", "title": "Ngày 5: Chinh phục sân gôn Laguna Lăng Cô", "description": "Chinh phục sân gôn Laguna Lăng Cô, thiết kế bởi Sir Nick Faldo, một trong những sân golf hàng đầu của Việt Nam. Nghỉ ngơi tại vịnh Lăng Cô thanh bình, nơi bạn có thể tận hưởng không khí trong lành và thư giãn."}, {"time": "10:00", "title": "Ngày 6: Ăn sáng và trả phòng", "description": "Ăn sáng tại khách sạn, làm thủ tục trả phòng, xe tiễn đoàn ra sân bay trở về nhà."}]'::jsonb, '["Lưu trú khách sạn 4-5 sao", "Đưa đón riêng biệt", "Xe điện buggy và caddy chuyên nghiệp tại mỗi sân"]'::jsonb, '["Ăn uống ngoài giờ", "Chi phí cá nhân"]'::jsonb, '17250000.00', '0.00', '0.00', 0, '6 ngày', '08:00', 'Sân bay Đà Nẵng, điểm hẹn lúc 08:00 sáng ngày 1', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804926/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p01__vmtravel-golf-in-hoi-an.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804926/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p01__vmtravel-golf-in-hoi-an.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804929/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p02__vmtravel-vietnam-luxury-golf-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804842/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p03__vmtravel-vietnam-golf-tour.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 4, '4.75', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(160, 'Tour Golf Đà Nẵng 4 Ngày Cao Cấp', 'vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang', 30, 'Dành riêng cho các gôn thủ muốn kết hợp nghỉ dưỡng và thỏa đam mê. Hành trình 4 ngày 3 đêm tại Đà Nẵng chơi gôn trên 3 sân gôn thiết kế tiêu chuẩn quốc tế đẹp nhất miền Trung Việt Nam, kết hợp xe đưa đón gôn sang trọng, dịch vụ caddy chuyên nghiệp, xe điện buggy và lưu trú khách sạn 4 sao cao cấp.', 'Trải nghiệm 3 sân gôn đẳng cấp quốc tế hàng đầu miền Trung', '[{"time": "08:00", "title": "Ngày 1: Đón Quý Khách tại Sân Bay Quốc Tế Đà Nẵng", "description": "Đón quý khách tại Sân bay Quốc tế Đà Nẵng, xe đưa đón quý khách về khách sạn 4 sao nhận phòng nghỉ ngơi, tự do khám phá thành phố về đêm. Quý khách có thể thưởng thức ẩm thực địa phương, tham quan các điểm du lịch nổi tiếng như Bãi biển Mỹ Khê, Quảng trường 30/4, hoặc đơn giản là thư giãn tại phòng khách sạn sau một chuyến bay dài."}, {"time": "07:00", "title": "Ngày 2: Trải Nghiệm Sân Golf Montgomerie Links", "description": "Dùng bữa sáng tại khách sạn, sau đó xe đưa đoàn đến sân Montgomerie Links, một trong những sân golf đẳng cấp quốc tế hàng đầu miền Trung. Trải nghiệm 18 hố golf trên một sân golf được thiết kế theo tiêu chuẩn quốc tế, với các hố golf đa dạng và thách thức. Chiều tự do tắm biển Mỹ Khê, một trong những bãi biển đẹp nhất Việt Nam."}, {"time": "07:00", "title": "Ngày 3: Trải Nghiệm Sân Golf BRG Đà Nẵng", "description": "Dùng điểm tâm sáng, sau đó trải nghiệm 18 hố golf tại BRG Da Nang Golf Resort, một sân golf đầy thách thức với các hố golf được thiết kế để thử sức các gôn thủ. Chiều tham quan Ngũ Hành Sơn và chùa Linh Ứng, hai điểm du lịch nổi tiếng của Đà Nẵng."}, {"time": "08:00", "title": "Ngày 4: Trải Nghiệm Sân Golf Vinpearl Nam Hội An", "description": "Ăn sáng, sau đó trả phòng khách sạn. Xe đưa đoàn đến Vinpearl Golf Nam Hội An, sân golf cuối cùng trong hành trình. Trải nghiệm 18 hố golf trên một sân golf được thiết kế theo tiêu chuẩn quốc tế, với các hố golf đa dạng và thách thức. Sau đó, tiễn sân bay về nước."}]'::jsonb, '["Xe đưa đón gôn sang trọng", "Dịch vụ caddy chuyên nghiệp", "Xe điện buggy", "Lưu trú khách sạn 4 sao cao cấp"]'::jsonb, '["Ăn uống ngoài giờ", "Dịch vụ phiêu lưu"]'::jsonb, '10625000.00', '0.00', '0.00', 0, '4 ngày', '08:00', 'Đón quý khách tại Sân bay Quốc tế Đà Nẵng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804835/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p01__vmtravel-da-nang-golf-courses.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804835/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p01__vmtravel-da-nang-golf-courses.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804838/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p02__vmtravel-brg-danang-golf-course.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804842/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p03__vmtravel-vietnam-golf-tour.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 5, '4.40', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(161, 'Tour động Thiên Đường từ Huế', 'vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece', 32, 'Hành trình trọn ngày vượt cung đường di sản miền Trung đi khám phá động Thiên Đường kì vĩ tại Vườn Quốc gia Phong Nha - Kẻ Bàng (Quảng Bình). Trên đường đi, du khách sẽ ghé viếng Thánh địa La Vang linh thiêng, đi qua sông Bến Hải, cầu Hiền Lương lịch sử và tận mắt chiêm ngưỡng vẻ đẹp thạch nhũ tráng lệ của hang động khô dài nhất châu Á.', 'Khám phá Động Thiên Đường - ''hoàng cung trong lòng đất'' kỳ vĩ tại Quảng Bình từ Huế, ghé viếng thánh địa La Vang.', '[{"time": "06:30", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn ở Huế", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn ở Huế, khởi hành đi Quảng Bình. Đây là bước đầu tiên của hành trình khám phá động Thiên Đường kì vĩ."}, {"time": "08:00", "title": "Viếng Thánh địa La Vang", "description": "Đến nơi, Quý khách sẽ được viếng Thánh địa La Vang - trung tâm hành hương Công giáo lớn nhất Việt Nam tại Quảng Trị. Đây là một trong những điểm đến linh thiêng và quan trọng của du khách."}, {"time": "09:30", "title": "Đi qua cụm di tích lịch sử cầu Hiền Lương - sông Bến Hải", "description": "Tiếp theo, xe sẽ đưa Quý khách đi qua cụm di tích lịch sử cầu Hiền Lương - sông Bến Hải tại vĩ tuyến 17. Quý khách sẽ được nghe giới thiệu lịch sử về những địa điểm này."}, {"time": "12:00", "title": "Dùng bữa trưa đặc sản vùng miền tại nhà hàng địa phương", "description": "Sau đó, xe sẽ đưa đoàn đến thị trấn Phong Nha, nơi Quý khách sẽ dùng bữa trưa đặc sản vùng miền tại nhà hàng địa phương. Đây là cơ hội để Quý khách trải nghiệm ẩm thực địa phương."}, {"time": "13:30", "title": "Xe đưa đoàn đến chân động Thiên Đường", "description": "Sau bữa trưa, xe sẽ đưa đoàn đến chân động Thiên Đường, nơi Quý khách sẽ bắt đầu hành trình khám phá động Thiên Đường kì vĩ."}, {"time": "14:00", "title": "Trung chuyển bằng xe điện và leo núi đi bộ lên lối vào động", "description": "Để đến được lối vào động, Quý khách sẽ phải trung chuyển bằng xe điện và leo núi đi bộ. Đây là một phần thú vị của hành trình khám phá động Thiên Đường."}, {"time": "15:00", "title": "Khám phá mê cung thạch nhũ lung linh, huyền ảo dưới ánh đèn của Động Thiên Đường", "description": "Cuối cùng, Quý khách sẽ được khám phá mê cung thạch nhũ lung linh, huyền ảo dưới ánh đèn của Động Thiên Đường trên cầu gỗ dài 1km. Đây là một trong những điểm nhấn của hành trình khám phá động Thiên Đường."}, {"time": "17:00", "title": "Trở ra ngoài núi, lên xe trở về Huế", "description": "Sau khi khám phá động Thiên Đường, Quý khách sẽ trở ra ngoài núi và lên xe trở về Huế. Đây là bước cuối cùng của hành trình khám phá động Thiên Đường kì vĩ."}]'::jsonb, '["Xe và hướng dẫn viên", "Ăn trưa đặc sản vùng miền", "Vé vào động Thiên Đường"]'::jsonb, '["Phí ăn sáng", "Phí lưu trú"]'::jsonb, '1600000.00', '0.00', '0.00', 0, '1 ngày', '06:30', 'Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn ở Huế.', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804952/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p01__vmtravel-paradise-cave-tour-from-hue.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804952/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p01__vmtravel-paradise-cave-tour-from-hue.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804955/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p02__vmtravel-paradise-cave-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804959/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p03__vmtravel-phong-nha-caves.jpg"]'::jsonb, NULL, 'active', 'open', false, false, 3, 0, 3, '4.67', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(162, 'Tour Thánh địa Mỹ Sơn từ cảng Tiên Sa', 'vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now', 57, 'Chuyến tham quan được thiết kế chuẩn mực đón trả tại cảng Tiên Sa giúp khách du lịch tàu biển khám phá Di sản Văn hóa Thế giới Thánh địa Mỹ Sơn. Tìm hiểu văn hóa nghệ thuật của vương triều Champa xưa, viếng các cụm đền tháp gạch nung cổ kính, thưởng thức múa Apsara cổ truyền và dùng bữa trưa đặc sản trước khi trở lại cảng.', 'Hành trình khám phá Thánh địa Mỹ Sơn cổ kính dành riêng cho du khách tàu biển', '[{"time": "08:00", "title": "Đón Quý khách tại cảng Tiên Sa", "description": "Đón Quý khách tại cảng Tiên Sa (trong hoặc ngoài cổng) khởi hành đi thẳng tới thung lũng di sản Thánh địa Mỹ Sơn. Lái xe sẽ hướng dẫn Quý khách cách thức di chuyển an toàn và nhanh chóng đến điểm đến."}, {"time": "09:30", "title": "Tham quan Thánh địa Mỹ Sơn", "description": "Đến Mỹ Sơn, đi bộ tham quan quần thể đền tháp gạch nung, lắng nghe hướng dẫn viên giới thiệu triết lý tôn giáo và lịch sử xây dựng tháp cổ. Quý khách sẽ được khám phá các cụm đền tháp gạch nung cổ kính và tìm hiểu về văn hóa nghệ thuật của vương triều Champa xưa."}, {"time": "11:00", "title": "Thưởng thức múa Apsara cổ truyền", "description": "Thưởng thức điệu múa cổ truyền Apsara duyên dáng tái hiện đời sống tinh thần Champa cổ xưa. Múa Apsara là một phần quan trọng của văn hóa nghệ thuật Champa và sẽ mang lại cho Quý khách một trải nghiệm độc đáo và đáng nhớ."}, {"time": "12:00", "title": "Thưởng thức bữa trưa đặc sản", "description": "Thưởng thức bữa trưa ấm cúng với ẩm thực địa phương miền Trung tại nhà hàng. Bữa trưa sẽ bao gồm các món ăn đặc sản của vùng miền Trung và sẽ mang lại cho Quý khách một trải nghiệm ẩm thực độc đáo và đáng nhớ."}, {"time": "13:30", "title": "Trở lại cảng Tiên Sa", "description": "Xe đưa đoàn trở lại cảng Tiên Sa, cam kết trả khách tại cảng trước giờ tàu rời bến ít nhất 1.5 giờ. Quý khách sẽ được lái xe an toàn và nhanh chóng trở lại cảng Tiên Sa."}]'::jsonb, '["Đón trả tại cảng Tiên Sa", "Tham quan Thánh địa Mỹ Sơn", "Thưởng thức múa Apsara cổ truyền", "Thưởng thức bữa trưa đặc sản"]'::jsonb, '["Phí ăn uống ngoài giờ", "Phí tham quan các điểm du lịch khác"]'::jsonb, '1350000.00', '0.00', '0.00', 0, '1 ngày', '08:00', 'Đón Quý khách tại cảng Tiên Sa (trong hoặc ngoài cổng)', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804943/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p01__vmtravel-my-son-sanctuary.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804943/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p01__vmtravel-my-son-sanctuary.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804946/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p02__vmtravel-my-son-holyland-tour.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804949/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p03__vmtravel-my-son-holyland.jpg"]'::jsonb, NULL, 'active', 'open', false, true, 3, 0, 6, '4.50', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(163, 'Tour Thánh địa Mỹ Sơn 1 ngày từ Hội An', 'vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an', 57, 'Chuyến du hành ngược thời gian tìm hiểu về vương quốc Champa cổ đại tại Thánh địa Mỹ Sơn - di sản văn hóa thế giới được UNESCO công nhận. Chiêm ngưỡng các ngọn tháp gạch nung hàng ngàn năm tuổi bí ẩn, thưởng thức điệu múa Chăm cổ xưa và ngồi thuyền ngắm hoàng hôn đỏ rực buông xuống trên dòng sông Thu Bồn yên bình.', 'Tham quan Thánh địa Mỹ Sơn và đi thuyền đón hoàng hôn trên sông Thu Bồn', '[{"time": "13:00", "title": "Xe và hướng dẫn viên đón Quý khách tại khách sạn cổ Hội An", "description": "Xe và hướng dẫn viên sẽ đón Quý khách tại khách sạn cổ Hội An, bắt đầu hành trình khám phá Thánh địa Mỹ Sơn."}, {"time": "13:30", "title": "Khởi hành đi Thánh địa Mỹ Sơn", "description": "Xe sẽ di chuyển đến Thánh địa Mỹ Sơn, một trong những di sản văn hóa thế giới được UNESCO công nhận."}, {"time": "15:00", "title": "Tự do đi bộ tham quan khu di tích đền tháp Champa cổ kính", "description": "Quý khách sẽ tự do đi bộ tham quan khu di tích đền tháp Champa cổ kính, tìm hiểu nền văn minh rực rỡ một thời của vương quốc Champa."}, {"time": "16:00", "title": "Thưởng thức điệu múa Apsara truyền thống", "description": "Quý khách sẽ được thưởng thức điệu múa Apsara truyền thống quyến rũ dưới chân tháp cổ, một trong những biểu tượng văn hóa của người Chăm."}, {"time": "17:15", "title": "Rời Mỹ Sơn, di chuyển ra bến thuyền gỗ", "description": "Sau khi tham quan Thánh địa Mỹ Sơn, xe sẽ rời đi và di chuyển ra bến thuyền gỗ để xuôi dòng sông Thu Bồn trở về Hội An."}, {"time": "18:30", "title": "Thuyền cập bến Hội An", "description": "Thuyền sẽ cập bến Hội An, xe sẽ đưa Quý khách về lại khách sạn kết thúc tour."}]'::jsonb, '["Xe và hướng dẫn viên", "Thuyền gỗ", "Điệu múa Apsara truyền thống"]'::jsonb, '["Ăn uống", "Phí tham quan"]'::jsonb, '875000.00', '0.00', '0.00', 0, 'Nửa ngày', '13:00', 'Khách sạn cổ Hội An', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804933/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p01__vmtravel-sunrise-at-my-son-sanctuary.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804933/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p01__vmtravel-sunrise-at-my-son-sanctuary.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804936/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p02__vmtravel-myson-sanctuary.jpg", "https://res.cloudinary.com/dmukxquza/image/upload/v1780804939/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p03__vmtravel-tour-my-son-sanctuary-from-hoi-an.jpg"]'::jsonb, NULL, 'active', 'open', false, true, 3, 0, 4, '4.50', NULL, '2026-06-13 10:20:55', '2026-06-15 03:35:39'),
(164, 'Tour Đà Nẵng đi Huế bằng tàu qua đèo Hải Vân', 'vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass', 59, 'Tour du lịch bằng đường sắt di sản độc nhất vô nhị. Du khách được ngồi trên đoàn tàu hoài cổ ngắm nhìn một bên là vách núi đèo Hải Vân hùng vĩ, một bên là vịnh Lăng Cô xanh ngắt. Sau đó, đặt chân đến Cố đô Huế để khám phá kiến trúc hoàng cung Đại Nội, chùa Thiên Mụ, lăng Khải Định cổ kính và trải nghiệm dịch vụ ngâm chân thảo dược hoàng gia.', 'Hành trình xe lửa du lịch di sản vượt đèo Hải Vân đi cố đô Huế trọn ngày từ Đà Nẵng, ngâm chân thảo dược cung đình.', '[{"time": "07:30", "title": "Xe đón Quý khách tại khách sạn Đà Nẵng", "description": "Xe sẽ đón Quý khách tại khách sạn Đà Nẵng và di chuyển đến Ga Đà Nẵng để làm thủ tục lên tàu di sản. Đây là bước đầu tiên của hành trình du lịch độc đáo này."}, {"time": "Trải nghiệm tàu hỏa du lịch vượt Đèo Hải Vân", "title": "Trải nghiệm tàu hỏa du lịch vượt Đèo Hải Vân", "description": "Sau khi làm thủ tục, Quý khách sẽ lên tàu hỏa di sản và bắt đầu hành trình vượt qua đèo Hải Vân. Trong quá trình di chuyển, Quý khách sẽ được ngắm nhìn vịnh Lăng Cô thơ mộng từ khung cửa sổ xe lửa tuyệt đẹp."}, {"time": "Đến ga Lăng Cô, xe đón đoàn đi Huế", "title": "Đến ga Lăng Cô, xe đón đoàn đi Huế", "description": "Khi đến ga Lăng Cô, xe sẽ đón đoàn và di chuyển đến Huế để tham quan Đại Nội Huế - hoàng cung của 13 vị vua triều Nguyễn xưa."}, {"time": "Thưởng thức bữa trưa đặc sản cung đình Huế", "title": "Thưởng thức bữa trưa đặc sản cung đình Huế", "description": "Sau khi tham quan Đại Nội Huế, Quý khách sẽ được thưởng thức bữa trưa đặc sản cung đình Huế. Đây là cơ hội để Quý khách trải nghiệm ẩm thực phong phú và đa dạng của Huế."}, {"time": "Thư giãn đôi chân với dịch vụ ngâm chân thảo dược hoàng gia", "title": "Thư giãn đôi chân với dịch vụ ngâm chân thảo dược hoàng gia", "description": "Sau bữa trưa, Quý khách sẽ được thư giãn đôi chân với dịch vụ ngâm chân thảo dược hoàng gia. Đây là cơ hội để Quý khách thư giãn và tái tạo năng lượng sau hành trình di chuyển."}, {"time": "Chiều: Viếng chùa Thiên Mụ cổ kính", "title": "Chiều: Viếng chùa Thiên Mụ cổ kính", "description": "Chiều, Quý khách sẽ được viếng chùa Thiên Mụ cổ kính bên dòng sông Hương thơ mộng. Đây là cơ hội để Quý khách khám phá kiến trúc cổ kính và lịch sử của chùa Thiên Mụ."}, {"time": "Chiều: Tham quan Lăng Khải Định", "title": "Chiều: Tham quan Lăng Khải Định", "description": "Sau khi viếng chùa Thiên Mụ, Quý khách sẽ được tham quan Lăng Khải Định với kiến trúc độc đáo bậc nhất. Đây là cơ hội để Quý khách khám phá kiến trúc và lịch sử của lăng Khải Định."}, {"time": "Tạm biệt cố đô, xe đưa đoàn trở lại Đà Nẵng", "title": "Tạm biệt cố đô, xe đưa đoàn trở lại Đà Nẵng", "description": "Cuối cùng, xe sẽ đưa đoàn trở lại Đà Nẵng qua hầm Hải Vân hiện đại. Đây là bước cuối cùng của hành trình du lịch độc đáo này."}, {"time": "18:00 - 18:30", "title": "Trả khách tại khách sạn Đà Nẵng", "description": "Cuối cùng, xe sẽ trả khách tại khách sạn Đà Nẵng, kết thúc chuyến đi."}]'::jsonb, '["Xe đưa đón, tàu hỏa di sản, bữa trưa đặc sản cung đình Huế, dịch vụ ngâm chân thảo dược hoàng gia"]'::jsonb, '["Vé vào cửa các điểm tham quan, nước uống, thức ăn vặt"]'::jsonb, '1625000.00', '0.00', '0.00', 0, '9 giờ', '07:30', 'Xe sẽ đón Quý khách tại khách sạn Đà Nẵng', 30, 1, NULL, NULL, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp", "https://res.cloudinary.com/