BEGIN;
-- Disable triggers
ALTER TABLE tours DISABLE TRIGGER ALL;

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    slug = EXCLUDED.slug,
    tour_category_id = EXCLUDED.tour_category_id,
    description = EXCLUDED.description,
    short_desc = EXCLUDED.short_desc,
    itinerary = EXCLUDED.itinerary,
    inclusions = EXCLUDED.inclusions,
    exclusions = EXCLUDED.exclusions,
    price_adult = EXCLUDED.price_adult,
    price_child = EXCLUDED.price_child,
    price_infant = EXCLUDED.price_infant,
    discount_percent = EXCLUDED.discount_percent,
    duration = EXCLUDED.duration,
    start_time = EXCLUDED.start_time,
    meeting_point = EXCLUDED.meeting_point,
    max_people = EXCLUDED.max_people,
    min_people = EXCLUDED.min_people,
    thumbnail = EXCLUDED.thumbnail,
    images = EXCLUDED.images,
    status = EXCLUDED.status,
    updated_at = NOW();

ON CONFLICT (id) DO UPDATE SET
    start_date = EXCLUDED.start_date,
    end_date = EXCLUDED.end_date,
    departure_code = EXCLUDED.departure_code,
    booking_deadline = EXCLUDED.booking_deadline,
    updated_at = NOW();


-- Re-enable triggers
ALTER TABLE tours ENABLE TRIGGER ALL;

SELECT setval(pg_get_serial_sequence('tours', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM tours), 1), true);
SELECT setval(pg_get_serial_sequence('tour_schedules', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM tour_schedules), 1), true);
SELECT setval(pg_get_serial_sequence('tour_locations', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM tour_locations), 1), true);

COMMIT;
